begin;

alter table public.product_catalog add column if not exists concerns jsonb not null default '[]'::jsonb;
alter table public.product_catalog add column if not exists primary_concern text;

insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('d-alloy-menopause-care-hormone-therapy-and-sexual', 'Alloy Menopause care (hormone therapy and sexual health)', 'Alloy', 'telehealth', 'digital', 'Alloy is an online menopause care service. It treats perimenopause, menopause and postmenopause symptoms with prescription estradiol (pill, gel, patch, Evamist spray) and offers vaginal estradiol cream, O-Mazing cream and a sexual health bundle. The page says all of its board-certified doctors specialize in menopause and midlife.', 'See the brand for current price', null, 'https://www.myalloy.com/', '["telehealth","menopause","perimenopause","hormone-support","skin","hyperpigmentation"]'::jsonb, '["telehealth","menopause","sexual-health"]'::jsonb, '["Alloy"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"Page lists no contraindications, eligibility rules or states served."}'::jsonb, null, null, null, 'brand', 'Product details are Alloy''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Alloy":"https://www.myalloy.com/"},"warnings":["Page lists no contraindications, eligibility rules or states served."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://www.myalloy.com/","what":"Homepage: services, product list, ''board-certified doctors'' wording, how it works, HSA/FSA eligible, no prices"}],"howToUse":{"intro":"Per Alloy''s product page:","steps":["Complete a medical intake (5-10 minutes).","Get a treatment plan (under 12 hours).","Get free delivery to your door.","Get 24/7 ongoing care and support."],"sourceUrl":"https://www.myalloy.com/","sourceLabel":"Alloy: product page"},"hiddenReason":"Not every fact is sourced yet: No price on the homepage (no membership, consult or product prices); no brand pricing page found; Page says ''board-certified doctors'', not ''licensed clinicians'' - use that wording; States served not stated; Also sells skincare, weight-loss (GLP-1), hair and gut products; sheet scope is menopause + sexual health only"}'::jsonb),
  ('d-twentyeight-health-birth-control-emergency-contr', 'Twentyeight Health Birth control, emergency contraception and urgent care', 'Twentyeight Health', 'contraception', 'digital', 'Twentyeight Health prescribes birth control online and delivers it at home: 100+ brands of the pill, patch, ring and shot, plus internal condoms. It also offers the morning-after pill and urgent care for UTI, herpes, BV and yeast infections. The page says a licensed provider reviews your answers and prescribes if you are eligible.', 'Pill from $16/pack without insurance; patch from $300/pack; ring from $130/pack; shot from $126 (3 months); morning-after pill $30; $0 copay with insurance incl. Medicaid on many items (brand page, Nov 2026)', null, 'https://www.twentyeighthealth.com/birth-control', '["contraception","telehealth","cost","uti","vaginal-health","privacy"]'::jsonb, '["contraception","telehealth"]'::jsonb, '["Twentyeight Health"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"The online quiz is not a medical diagnosis and does not replace a provider''s assessment. Emergency contraception is for use within 3-5 days after unprotected sex."}'::jsonb, null, null, null, 'brand', 'Product details are Twentyeight Health''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Twentyeight Health":"https://www.twentyeighthealth.com/birth-control"},"warnings":["The online quiz is not a medical diagnosis and does not replace a provider''s assessment.","Emergency contraception is for use within 3-5 days after unprotected sex."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://www.twentyeighthealth.com/birth-control","what":"Offerings, prices, ''licensed provider'' wording, how it works, insurance/Medicaid, FAQ warnings"}],"howToUse":{"intro":"Per Twentyeight Health''s product page:","steps":["Complete a medical questionnaire (under 5 minutes).","A licensed provider reviews it and prescribes if eligible, or asks follow-up questions.","Get ongoing care: prescription changes, 24/7 provider access, free shipping."],"sourceUrl":"https://www.twentyeighthealth.com/birth-control","sourceLabel":"Twentyeight Health: product page"},"optionsNote":"Options: Pill, Patch, Ring, Shot, Emergency contraception, Urgent care."}'::jsonb),
  ('d-function-health-function-health-membership', 'Function Health Membership', 'Function Health', 'diagnostics', 'digital', 'Function Health is a yearly membership for 160+ lab tests, done twice a year, at Quest locations or with an at-home draw. Panels cover hormones and fertility, thyroid, heart, metabolic, nutrients, autoimmunity and toxins. The page says clinicians review every result and you get a personal action plan.', '$365 per year, billed annually; HSA/FSA eligible; first-year price excludes NY and NJ (brand page, Nov 2026)', null, 'https://www.functionhealth.com/pricing', '["hormone-monitoring","fertility"]'::jsonb, '["fertility"]'::jsonb, '["Function Health"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"Function Health says it is a technology company, not a lab or medical provider, and does not give medical advice, diagnosis or treatment. Not a substitute for medical care or talking with a physician. Add-on tests and imaging cost extra."}'::jsonb, null, null, null, 'brand', 'Product details are Function Health''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Function Health":"https://www.functionhealth.com/pricing"},"warnings":["Function Health says it is a technology company, not a lab or medical provider, and does not give medical advice, diagnosis or treatment.","Not a substitute for medical care or talking with a physician.","Add-on tests and imaging cost extra."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://www.functionhealth.com/pricing","what":"Price, tests included, how it works, clinician review wording, NY/NJ exclusion, disclaimers"}],"howToUse":{"intro":"Per Function Health''s product page:","steps":["Get 160+ lab tests at a Quest location or with an at-home draw by a licensed specialist.","Clinicians review results and flag issues.","Follow your personal plan, then test again."],"sourceUrl":"https://www.functionhealth.com/pricing","sourceLabel":"Function Health: product page"}}'::jsonb),
  ('p-elladx-ella-dx-annual-panel', 'EllaDx Ella Dx Annual Panel', 'EllaDx', 'diagnostics', 'physical', 'The Ella Dx Annual is a yearly blood panel for women who want to look into ongoing symptoms or set a baseline, especially in their 30s, 40s and 50s. It includes thyroid (TSH, Free T4), IGF-1, HbA1c, lipids, vitamin D, hs-CRP, CBC and CMP. A licensed physician signs the lab order, but EllaDx does not interpret individual results.', '$79 for the Annual panel; at-home blood draw +$75 where available (brand page, Nov 2026)', 'https://elladx.com/images/product-images/6/06a7d742-3507-40e3-8a6f-a3d836e37fdc.jpg', 'https://elladx.com/what-we-test/ella-dx-annual', '["hormone-monitoring","fatigue"]'::jsonb, '["fertility"]'::jsonb, '["EllaDx"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"Not a substitute for medical diagnosis or an annual exam. The biological age score is an estimate, not a diagnosis. Talk to a qualified clinician before changing your care."}'::jsonb, null, null, null, 'brand', 'Product details are EllaDx''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"EllaDx":"https://elladx.com/what-we-test/ella-dx-annual"},"warnings":["Not a substitute for medical diagnosis or an annual exam.","The biological age score is an estimate, not a diagnosis.","Talk to a qualified clinician before changing your care."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://elladx.com/what-we-test/ella-dx-annual","what":"Price, marker list, collection, how it works, physician-signed requisition, disclaimers, og:image"}],"howToUse":{"intro":"Per EllaDx''s product page:","steps":["Order online, answer health questions and book a lab or at-home draw.","Fast 8-12 hours (water OK); morning draw recommended; take thyroid tests before morning thyroid medicine; hold biotin and high-dose vitamin D 24-48 hours before.","Give your sample at a partner lab or at home (about 10 minutes).","See results in a secure portal, usually in about 5 days."],"sourceUrl":"https://elladx.com/what-we-test/ella-dx-annual","sourceLabel":"EllaDx: product page"},"hiddenReason":"Not every fact is sourced yet: Sheet says ''Hormones / Thyroid / Fertility / Anemia panels'' but this page does NOT list estrogen, progesterone, testosterone, FSH, LH, AMH, ferritin or iron. Only thyroid is clearly covered. Other EllaDx panels were not on this page and were not researched; Page is inconsistent: ''74 lab markers'' vs FAQ ''Why these 9 tests?''; Do not tag fertility/anemia until a page that lists those markers is read; fatigue tag is weak (page says ''ongoing symptoms'' only); consider dropping"}'::jsonb),
  ('p-hormona-perimenopause-test-kit-app', 'Hormona Perimenopause Test Kit + App', 'Hormona', 'diagnostics', 'physical', 'An at-home urine test kit that works with the Hormona app to track estrogen (E3G), progesterone (PdG) and FSH. The app sets a testing schedule that adapts to irregular or absent periods and shows a perimenopause stage after 15 tests. It is for women 40+ and does not diagnose hormonal imbalances or medical conditions.', '£249 for 3 months (15 tests); £429 for 6 months (30 tests); £729 for 12 months (60 tests); free 12-month Hormona+ app subscription with kit until 30/11 (brand page, Nov 2026, GBP)', 'https://www.hormona.io/cdn/shop/files/Main_Product_Image_6.png?v=1791895514', 'https://www.hormona.io/products/perimenopause-test', '["perimenopause","hormone-monitoring","menopause","irregular"]'::jsonb, '["perimenopause","menopause"]'::jsonb, '["Hormona"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02)","materials":"Urine test strips (FSH, estrone-3-glucuronide, pregnanediol glucuronide); full box contents not itemized on page","sideEffects":"Does not diagnose hormonal imbalances or medical conditions. Results can be affected by hydration or liver or kidney conditions. Avoid fluids 1-2 hours before bed and avoid alcohol and foods that change urine color. Not currently optimized for people on HRT."}'::jsonb, null, null, null, 'brand', 'Product details are Hormona''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Hormona":"https://www.hormona.io/products/perimenopause-test"},"warnings":["Does not diagnose hormonal imbalances or medical conditions.","Results can be affected by hydration or liver or kidney conditions.","Avoid fluids 1-2 hours before bed and avoid alcohol and foods that change urine color.","Not currently optimized for people on HRT."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://www.hormona.io/products/perimenopause-test","what":"Hormones measured, prices (GBP), app features, steps, warnings, image"},{"url":"https://api.fda.gov/device/registrationlisting.json?search=proprietary_name:\"Hormona\"&limit=5","what":"openFDA registration query - no match (4xx)"}],"ingredients":"Urine test strips (FSH, estrone-3-glucuronide, pregnanediol glucuronide); full box contents not itemized on page","howToUse":{"intro":"Per Hormona''s product page:","steps":["Order the kit and download the app to activate it.","The app tells you when and which hormone to test.","Dip the strip in first-morning urine and wait 15 minutes (the app times it).","Scan the strip with your phone in good light to get your result."],"sourceUrl":"https://www.hormona.io/products/perimenopause-test","sourceLabel":"Hormona: product page"},"optionsNote":"Options: 3 months (15 tests), 6 months (30 tests), 12 months (60 tests)."}'::jsonb),
  ('p-clearblue-menopause-stage-indicator', 'Clearblue Menopause Stage Indicator', 'Clearblue', 'diagnostics', 'physical', 'A home urine test kit with a free app that tracks FSH over five tests on alternate days. After the fifth test it shows your likely stage: premenopause, early perimenopause, late perimenopause or postmenopause. The app also logs up to 19 symptoms and makes a report to share with your healthcare professional.', 'See the brand for current price', null, 'https://clearblue.com/menopause/stage-indicator', '["perimenopause","menopause","hormone-monitoring"]'::jsonb, '["perimenopause","menopause"]'::jsonb, '["Clearblue"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-registered/listed maker: SPD Development Company Limited is listed for product code NGA (OTC FSH test, Class 1). The listing shows no proprietary name, so this exact product is not named in openFDA.","materials":"5 urine test sticks (FSH) plus activation code for the free Clearblue me app","sideEffects":"Only a healthcare professional can confirm your menopause stage; this is not a diagnosis. Symptoms can overlap with other health conditions."}'::jsonb, null, null, null, 'brand', 'Product details are Clearblue''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Clearblue":"https://clearblue.com/menopause/stage-indicator"},"warnings":["Only a healthcare professional can confirm your menopause stage; this is not a diagnosis.","Symptoms can overlap with other health conditions."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://clearblue.com/menopause/stage-indicator","what":"What it measures, 5 tests, steps, app, limitations; no price"},{"url":"https://api.fda.gov/device/registrationlisting.json?search=products.product_code:NGA+AND+registration.name:\"SPD\"&limit=10","what":"SPD listed under NGA Class 1, no proprietary name"},{"url":"https://api.fda.gov/device/registrationlisting.json?search=proprietary_name:\"Menopause Stage Indicator\"&limit=5","what":"Only Teco Diagnostics match"}],"ingredients":"5 urine test sticks (FSH) plus activation code for the free Clearblue me app","howToUse":{"intro":"Per Clearblue''s product page:","steps":["Download the free app, create an account, enter the activation code and set your test schedule at least a day before the first test.","Test with first-morning urine: hold the tip pointing down in your urine stream, recap and lay flat. Avoid heavy bleeding days.","Wait 5 full minutes.","Read within 8 minutes: two lines is positive at any intensity; no control line means the test failed, so log it and retest on your next test day.","Your likely stage shows after the fifth test."],"sourceUrl":"https://clearblue.com/menopause/stage-indicator","sourceLabel":"Clearblue: product page"},"hiddenReason":"Not every fact is sourced yet: No price on brand page; Amazon link (B0C68D39LQ) could not be read (robots blocked), so ASIN match unverified; No product image URL from page; Page does not address hormonal contraception or HRT users, pregnancy or breastfeeding"}'::jsonb),
  ('d-balance-balance-menopause-hormones', 'Balance - Menopause & Hormones', 'Balance', 'menopause', 'digital', 'A free menopause and hormone health app from Balance App Limited, founded by Dr Louise Newson. It has articles, symptom and period tracking, mood and sleep tracking, a Health Report to take to appointments and a community forum. The optional balance+ subscription adds live expert sessions, Pilates, yoga and meditation.', 'Free; optional balance+ subscription listed at $4.99/month or $49.99/year (other tiers listed: $3.99, $10.99/month, $98.99/year) (App Store, Nov 2026)', null, 'https://apps.apple.com/us/app/id1503345959', '["menopause","perimenopause","sleep","stress"]'::jsonb, '["menopause","perimenopause","cycle-tracking"]'::jsonb, '["Balance"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"No medical disclaimer on the App Store page."}'::jsonb, null, null, null, 'brand', 'Product details are Balance''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Balance":"https://apps.apple.com/us/app/id1503345959"},"warnings":["No medical disclaimer on the App Store page."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://apps.apple.com/us/app/id1503345959","what":"App Store listing: description, developer, price and in-app purchases, age rating"}]}'::jsonb),
  ('d-caria-caria-menopause-midlife', 'Caria: Menopause & Midlife', 'Caria', 'menopause', 'digital', 'A menopause support app for tracking symptoms and daily habits, getting personal insights and connecting with other women in menopause. It has courses on nutrition, mindfulness and CBT techniques, and short audio exercises for hot flashes and insomnia. The app says it is not a replacement for professional medical help.', 'Free; Caria Premium $5.99/month or $47.99/year per App Store purchase list (description text says $9.99/month, $49.99/year) (App Store, Nov 2026)', null, 'https://apps.apple.com/us/app/id1477621356', '["menopause","sleep","stress"]'::jsonb, '["menopause","mental-health","sleep"]'::jsonb, '["Caria"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"Caria is not a replacement for professional medical help; talk to a doctor about symptoms."}'::jsonb, null, null, null, 'brand', 'Product details are Caria''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Caria":"https://apps.apple.com/us/app/id1477621356"},"warnings":["Caria is not a replacement for professional medical help; talk to a doctor about symptoms."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://apps.apple.com/us/app/id1477621356","what":"App Store listing: description, developer, price and in-app purchases, age rating"}]}'::jsonb),
  ('d-health-her-health-her-app', 'Health & Her App', 'Health & Her', 'tracker', 'digital', 'A free hormonal health tracker for any life stage, including natural cycles, hormonal contraception, HT, perimenopause and menopause. Users log symptoms and mood, spot patterns and can predict periods. It includes CBT exercises, pelvic floor training, sleep audio, reminders and expert articles, reviewed by Dr Harriet Connell.', 'Free; no in-app purchases listed (App Store, Nov 2026)', null, 'https://apps.apple.com/us/app/id1519199698', '["menopause","perimenopause","pelvic-floor","sleep","stress"]'::jsonb, '["cycle-tracking","perimenopause","pelvic-floor"]'::jsonb, '["Health & Her"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"No medical disclaimer on the App Store page."}'::jsonb, null, null, null, 'brand', 'Product details are Health & Her''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Health & Her":"https://apps.apple.com/us/app/id1519199698"},"warnings":["No medical disclaimer on the App Store page."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://apps.apple.com/us/app/id1519199698","what":"App Store listing: description, developer, price and in-app purchases, age rating"}]}'::jsonb),
  ('d-stella-stella-menopause-relief', 'Stella: Menopause relief', 'Stella', 'menopause', 'digital', 'A menopause care app from Vira Health that builds a personal plan of healthy habits for specific symptoms. It includes articles, video workouts, recipes, audio meditations, coach chat and expert events. The listing says it is available only through partners such as health insurers and employers.', 'Listed as free with in-app purchases: $22.49/month, $45.99/quarter, $79.99/year; App Store page says the app is available only through partners such as insurers and employers (App Store, Nov 2026)', null, 'https://apps.apple.com/us/app/id1577904186', '["menopause","perimenopause","sleep"]'::jsonb, '["menopause","perimenopause"]'::jsonb, '["Stella"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"No medical disclaimer on the App Store page."}'::jsonb, null, null, null, 'brand', 'Product details are Stella''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Stella":"https://apps.apple.com/us/app/id1577904186"},"warnings":["No medical disclaimer on the App Store page."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://apps.apple.com/us/app/id1577904186","what":"App Store listing: description, developer, price and in-app purchases, age rating"}]}'::jsonb),
  ('d-perry-perry-perimenopause-community', 'perry: Perimenopause Community', 'perry', 'menopause', 'digital', 'A free community app for women in perimenopause and menopause. It has topic groups, chat and posts for sharing experiences, plus expert-led courses, live events and a private journal you can share by link.', 'Free; subscription $7.99/month or $79.00/year (App Store, Nov 2026)', null, 'https://apps.apple.com/us/app/id1544428724', '["perimenopause","menopause","stress"]'::jsonb, '["perimenopause","mental-health"]'::jsonb, '["perry"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"No medical disclaimer on the App Store page. Contains user-generated content and unrestricted web access (age 16+)."}'::jsonb, null, null, null, 'brand', 'Product details are perry''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"perry":"https://apps.apple.com/us/app/id1544428724"},"warnings":["No medical disclaimer on the App Store page.","Contains user-generated content and unrestricted web access (age 16+)."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://apps.apple.com/us/app/id1544428724","what":"App Store listing: description, developer, price and in-app purchases, age rating"}]}'::jsonb),
  ('d-menolog-listed-as-menelle-perimenopause-tracker', 'Menolog (listed as Menelle) Perimenopause Tracker: Menelle', 'Menolog (listed as Menelle)', 'tracker', 'digital', 'A tracker app from Ten Labs Ltd for perimenopause and menopause symptoms, medications, supplements and periods, plus custom trackers. Pro adds a meal-photo scan for foods that may trigger or ease symptoms, longer trend views and doctor-ready PDF reports. The app says it is not a medical device and does not replace medical advice.', 'Free; Menolog Pro in-app purchase listed at $5.99 and $29.99 (likely monthly/yearly, not stated) (App Store, Nov 2026)', null, 'https://apps.apple.com/us/app/id6757102221', '["perimenopause","menopause","supplement"]'::jsonb, '["perimenopause","menopause","cycle-tracking"]'::jsonb, '["Menolog (listed as Menelle)"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"Not a medical device; does not replace professional medical advice. Meal scan insights are general nutrition information, not medical guidance."}'::jsonb, null, null, null, 'brand', 'Product details are Menolog (listed as Menelle)''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Menolog (listed as Menelle)":"https://apps.apple.com/us/app/id6757102221"},"warnings":["Not a medical device; does not replace professional medical advice.","Meal scan insights are general nutrition information, not medical guidance."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://apps.apple.com/us/app/id6757102221","what":"App Store listing: name Menelle, Menolog Pro IAPs, features, disclaimer"}]}'::jsonb),
  ('d-lively-lively-period-tracker-cycle', 'Lively - Period Tracker, Cycle', 'Lively', 'tracker', 'digital', 'Lively is a cycle syncing and period tracking app. It logs periods and symptoms, predicts the next period and suggests food, movement and rest ideas for each phase. It also has pregnancy and postpartum tracking, partner syncing, an AI advisor and PDF reports for your care team.', 'Free download; optional Premium, App Store lists e.g. $4.99/month, $2.99/week, annual $18.99-$39.99 (App Store, Nov 2026)', 'https://livelycycle.com/og-image.jpg', 'https://livelycycle.com/', '["pregnancy","postpartum","perimenopause"]'::jsonb, '["cycle-tracking"]'::jsonb, '["Lively"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not an FDA-regulated device as listed","sideEffects":"No medical disclaimer on the homepage or App Store page."}'::jsonb, null, null, null, 'brand', 'Product details are Lively''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Lively":"https://livelycycle.com/"},"warnings":["No medical disclaimer on the homepage or App Store page."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://livelycycle.com/","what":"Homepage: features, free with optional Premium, og:image, App Store link"},{"url":"https://apps.apple.com/US/app/id6447674634","what":"App Store: price list, developer Lively Cycle LLC, perimenopause/menopause tracking"}]}'::jsonb),
  ('p-replens-long-lasting-vaginal-moisturizer', 'Replens Long-Lasting Vaginal Moisturizer', 'Replens', 'intimate-care', 'physical', 'An internal vaginal moisturizer that relieves vaginal dryness and helps replenish vaginal moisture. The page links dryness to estrogen decline from childbirth, breastfeeding or menopause, and to some medications, intense exercise and stress. It is estrogen-free and hormone-free.', 'See the brand for current price', 'https://www.replens.com/images/product-images/replens-long-lasting-moisturizer-01.jpg', 'https://www.replens.com/en/products/replens-long-lasting-moisturizer', '["vaginal-health","discomfort","menopause","postpartum","hormone-free","fragrance-free"]'::jsonb, '["vaginal-health","comfort","menopause"]'::jsonb, '["Replens"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"510(k)-cleared (K203818; earlier K101241 and K101098) and FDA-registered/listed (product code NUC, Class 2)","materials":"No full list on the brand page. FAQ says it contains glycerin and uses a bio-adhesive technology.","allergens":"Not listed. Page says fragrance-free and paraben-free.","sideEffects":"Do not use scissors or sharp tools to cut the applicator open. Do not reuse disposable applicators. Stop use four days before a pap smear. Discharge may occur if used during a period; resume after flow stops. Does not contain spermicide. It is not a contraceptive. Compatible with natural rubber latex and polyisoprene condoms; not compatible with polyurethane condoms."}'::jsonb, null, null, null, 'brand', 'Product details are Replens''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Replens":"https://www.replens.com/en/products/replens-long-lasting-moisturizer"},"warnings":["Do not use scissors or sharp tools to cut the applicator open.","Do not reuse disposable applicators.","Stop use four days before a pap smear.","Discharge may occur if used during a period; resume after flow stops.","Does not contain spermicide. It is not a contraceptive.","Compatible with natural rubber latex and polyisoprene condoms; not compatible with polyurethane condoms."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://www.replens.com/en/products/replens-long-lasting-moisturizer","what":"brand product page: description, sizes, directions, warnings, condom compatibility, FDA wording"},{"url":"https://api.fda.gov/device/510k.json?search=device_name:\"Replens\"&limit=10","what":"openFDA 510(k)"},{"url":"https://api.fda.gov/device/registrationlisting.json?search=proprietary_name:\"Replens\"&limit=5","what":"openFDA registration/listing"}],"ingredients":"No full list on the brand page. FAQ says it contains glycerin and uses a bio-adhesive technology.","howToUse":{"intro":"Per Replens''s product page:","steps":["Use about every three days; page says it is safe to use daily.","Use any time of day, ideally at least 2 hours before intercourse.","Disposable applicator: twist off the tab, insert, squeeze 2-3 times, then discard.","Reusable applicator: fill to the plunger stop, insert, press the plunger, then wash and dry both parts."],"sourceUrl":"https://www.replens.com/en/products/replens-long-lasting-moisturizer","sourceLabel":"Replens: product page"},"optionsNote":"Options: 8-count single-use pre-filled applicators, 35g tube with reusable applicator (14 applications).","hiddenReason":"Not every fact is sourced yet: Price not shown on brand page.; Full ingredient list not on brand page.; Pregnancy/breastfeeding not addressed.; Amazon listing could not be read (WebFetch blocked by amazon.com robots); ASIN not verified."}'::jsonb),
  ('p-replens-external-comfort-gel', 'Replens External Comfort Gel', 'Replens', 'intimate-care', 'physical', 'A gel for the skin around the vulva that soothes discomfort from external vaginal dryness. The page links this dryness to menopause, perimenopause, medications and hormone changes. It is estrogen-free, hormone-free and fragrance-free.', 'See the brand for current price', 'https://www.replens.com/images/product-images/replens-moisture-restore-external-comfort-gel-01.jpg', 'https://www.replens.com/en/products/replens-moisture-restore-external-comfort-gel', '["external-only","discomfort","menopause","perimenopause","hormone-free","fragrance-free","skin"]'::jsonb, '["vaginal-health","comfort","menopause"]'::jsonb, '["Replens"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Brand page shows a ''CLINICALLY-TESTED, FDA APPROVED'' badge: per the brand; not found in openFDA. No FDA listing found for this product (checked openFDA 2026-11-02).","materials":"No full list on the brand page. Names a ''Hydrapro Complex'' including vitamin E and pro-vitamin B5.","sideEffects":"Use only on the skin outside the vagina. Does not contain spermicide. It is not a contraceptive. Ask your doctor if it can help with dryness symptoms."}'::jsonb, null, null, null, 'brand', 'Product details are Replens''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Replens":"https://www.replens.com/en/products/replens-moisture-restore-external-comfort-gel"},"warnings":["Use only on the skin outside the vagina.","Does not contain spermicide. It is not a contraceptive.","Ask your doctor if it can help with dryness symptoms."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://www.replens.com/en/products/replens-moisture-restore-external-comfort-gel","what":"brand product page"},{"url":"https://api.fda.gov/device/registrationlisting.json?search=proprietary_name:\"Replens\"&limit=5","what":"openFDA registration (no gel listed)"}],"ingredients":"No full list on the brand page. Names a ''Hydrapro Complex'' including vitamin E and pro-vitamin B5.","howToUse":{"intro":"Per Replens''s product page:","steps":["Wash hands before and after application.","Squeeze out a fingertip amount and apply to the external vaginal area.","Use daily or as needed, any time of day or night."],"sourceUrl":"https://www.replens.com/en/products/replens-moisture-restore-external-comfort-gel","sourceLabel":"Replens: product page"},"hiddenReason":"Not every fact is sourced yet: Price and size not shown on brand page.; Full ingredient list not on page.; Allergens, pregnancy, breastfeeding not addressed.; Condom compatibility not stated (brand recommends Silky Smooth for sex)."}'::jsonb),
  ('p-replens-silky-smooth-silicone-based-lubricant', 'Replens Silky Smooth Silicone-Based Lubricant', 'Replens', 'intimate-care', 'physical', 'A silicone-based personal lubricant that reduces friction and adds glide during sex. The page says it supports comfort for people with vaginal dryness, including dryness linked to menopause or medications. Lubricant base: silicone. Condoms: page says compatible with natural rubber latex, polyisoprene and polyurethane condoms.', 'See the brand for current price', 'https://www.replens.com/images/product-images/replens-silky-smooth-lubricant-01.jpg', 'https://www.replens.com/en/products/replens-silky-smooth-lubricant', '["comfort","discomfort","menopause","hormone-free","fragrance-free"]'::jsonb, '["sexual-health","comfort"]'::jsonb, '["Replens"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-registered/listed (product code NUC, Class 2). No 510(k) found under the Replens or Silky Smooth name. Brand page shows ''CLINICALLY-TESTED, FDA APPROVED'': per the brand; approval not found in openFDA.","materials":"No full list on the brand page. Page says free from parabens, fragrances, preservatives, glycerin, petrochemicals, propylene glycol, estrogen/hormones and gluten.","allergens":"Not listed. Page says gluten-free and fragrance-free.","sideEffects":"Five-year shelf life; expiration date on carton bottom (YYMMDD)."}'::jsonb, null, null, null, 'brand', 'Product details are Replens''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Replens":"https://www.replens.com/en/products/replens-silky-smooth-lubricant"},"warnings":["Five-year shelf life; expiration date on carton bottom (YYMMDD)."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://www.replens.com/en/products/replens-silky-smooth-lubricant","what":"brand product page"},{"url":"https://api.fda.gov/device/registrationlisting.json?search=proprietary_name:\"Silky Smooth\"&limit=5","what":"openFDA registration"},{"url":"https://api.fda.gov/device/510k.json?search=applicant:church+AND+applicant:dwight+AND+product_code:NUC&limit=20","what":"openFDA 510(k) for Church & Dwight lubricants"}],"ingredients":"No full list on the brand page. Page says free from parabens, fragrances, preservatives, glycerin, petrochemicals, propylene glycol, estrogen/hormones and gluten.","howToUse":{"intro":"Per Replens''s product page:","steps":["Apply a small amount where extra lubrication is wanted, before sex.","Reapply as needed.","Tasteless and odorless, so it can be used for oral sex.","Clean fabrics and surfaces right away with mild soap and warm water.","Store at room temperature with the cap closed."],"sourceUrl":"https://www.replens.com/en/products/replens-silky-smooth-lubricant","sourceLabel":"Replens: product page"},"hiddenReason":"Not every fact is sourced yet: Price and size not shown on brand page.; Full ingredient list not on page.; Toy compatibility not stated.; Pregnancy/breastfeeding not addressed."}'::jsonb),
  ('p-kindra-v-relief-serum', 'Kindra V Relief Serum', 'Kindra', 'intimate-care', 'physical', 'A serum for vulvar and vaginal discomfort and sensitivity, applied to the vulva, labia and vaginal opening. The page says it is for people with burning, itching, dryness or sensitivity, including hormonal changes from oral contraceptives, postpartum and menopause. It contains a peptide, hyaluronic acid, vitamin E and coconut oil, and is made without hormones, parabens or fragrance.', 'From $29 (1 oz); page also shows $49 sale / $72 regular without saying which size (brand page, Nov 2026)', 'https://ourkindra.com/cdn/shop/files/V_Relief_Serum_1oz_Box_-_Front_Back_3.jpg?v=1791588501', 'https://ourkindra.com/products/v-relief-serum', '["vaginal-health","discomfort","menopause","postpartum","hormone-free","fragrance-free","skin"]'::jsonb, '["vaginal-health","comfort","menopause"]'::jsonb, '["Kindra"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Listed in openFDA as a HUMAN OTC DRUG label (active ingredient Dimethicone 2%), manufacturer Kindra. This is a drug listing, not an FDA approval. No device listing.","materials":"Water, Hydroxypropyl Starch Phosphate, Propanediol, Dimethicone, Glycerin, Butyrospermum Parkii (Shea) Butter, Lactic Acid, Sodium Benzoate, Potassium Sorbate, Hydrogenated Lecithin, Akebia Quinata Extract, Sodium Hyaluronate, Phenethyl Alcohol, Ethylhexylglycerin, Maltodextrin, Pentapeptide-59, Tocopheryl Acetate (Vitamin E), Cocos Nucifera (Coconut) Oil (page notes packaging is authoritative)","allergens":"Not listed. Page says hypoallergenic; contains coconut oil and shea butter.","sideEffects":"Statements not evaluated by the FDA; not intended to diagnose, treat, cure or prevent any disease (page disclaimer)."}'::jsonb, null, null, null, 'brand', 'Product details are Kindra''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Kindra":"https://ourkindra.com/products/v-relief-serum"},"warnings":["Statements not evaluated by the FDA; not intended to diagnose, treat, cure or prevent any disease (page disclaimer)."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://ourkindra.com/products/v-relief-serum","what":"brand product page: ingredients, use, sizes"},{"url":"https://ourkindra.com/products/the-daily-vaginal-lotion","what":"Daily V Lotion page: different ingredient list, listed as separate product"},{"url":"https://api.fda.gov/drug/label.json?search=openfda.manufacturer_name:kindra&limit=5","what":"openFDA drug labels"}],"ingredients":"Water, Hydroxypropyl Starch Phosphate, Propanediol, Dimethicone, Glycerin, Butyrospermum Parkii (Shea) Butter, Lactic Acid, Sodium Benzoate, Potassium Sorbate, Hydrogenated Lecithin, Akebia Quinata Extract, Sodium Hyaluronate, Phenethyl Alcohol, Ethylhexylglycerin, Maltodextrin, Pentapeptide-59, Tocopheryl Acetate (Vitamin E), Cocos Nucifera (Coconut) Oil (page notes packaging is authoritative)","howToUse":{"intro":"Per Kindra''s product page:","steps":["Apply with clean, dry fingers to the vulva, including the labia and vaginal opening.","Apply morning and night for best results.","Can be applied before and after intimacy."],"sourceUrl":"https://ourkindra.com/products/v-relief-serum","sourceLabel":"Kindra: product page"},"optionsNote":"Options: 1 oz, 2.5 oz, 2-pack 1 oz, 2-pack 2.5 oz."}'::jsonb),
  ('p-kindra-v-lube-water-based-lubricant', 'Kindra V Lube Water-Based Lubricant', 'Kindra', 'intimate-care', 'physical', 'A pH-balanced (pH 3.5 to 4.75), plant-based water-based gel lubricant for partnered or solo sex. The page says it is for people who had irritation or recurring infections with other lubes, or dryness from hormonal changes, menopause, postpartum, medications or birth control. Lubricant base: water. Condoms: page says compatible with natural rubber latex and polyisoprene condoms, not polyurethane.', '$19 (size not listed) (brand page, Nov 2026)', 'https://ourkindra.com/cdn/shop/files/VLubeWater_Primary_and_Secondary_EDITED_3.jpg?v=1784059121', 'https://ourkindra.com/products/v-lube-water-based-lubricant', '["comfort","discomfort","menopause","postpartum","vaginal-health","ph-neutral","fragrance-free"]'::jsonb, '["sexual-health","comfort","vaginal-health"]'::jsonb, '["Kindra"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Brand page shows an ''FDA-cleared'' badge and says it is ''registered with the FDA as a personal lubricant device'': per the brand; not found in openFDA. No FDA listing found (checked openFDA 2026-11-02).","materials":"Water (Aqua), Propanediol, Gluconolactone, Hydroxyethylcellulose, Sodium Benzoate, Citric Acid","allergens":"No allergen statement. Page says hypoallergenic; no glycerin, parabens, oils or fragrance.","sideEffects":"For sexual activity; page says it is not a vaginal moisturizer. Not formulated for ingestion; not a food product. Not compatible with polyurethane condoms. Compatible with all toy materials, wands and dilators."}'::jsonb, null, null, null, 'brand', 'Product details are Kindra''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Kindra":"https://ourkindra.com/products/v-lube-water-based-lubricant"},"warnings":["For sexual activity; page says it is not a vaginal moisturizer.","Not formulated for ingestion; not a food product.","Not compatible with polyurethane condoms.","Compatible with all toy materials, wands and dilators."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://ourkindra.com/products/v-lube-water-based-lubricant","what":"brand product page"},{"url":"https://api.fda.gov/device/510k.json?search=applicant:\"kindra\"","what":"openFDA 510(k), no match"}],"ingredients":"Water (Aqua), Propanediol, Gluconolactone, Hydroxyethylcellulose, Sodium Benzoate, Citric Acid","howToUse":{"intro":"Per Kindra''s product page:","steps":["Apply generously to the area you wish to lubricate.","Reapply as desired.","Cleans off with soap and water."],"sourceUrl":"https://ourkindra.com/products/v-lube-water-based-lubricant","sourceLabel":"Kindra: product page"}}'::jsonb),
  ('p-kindra-v-lube-silicone-lubricant', 'Kindra V Lube Silicone Lubricant', 'Kindra', 'intimate-care', 'physical', 'Kindra''s silicone-based personal lubricant. It is paraben-, glycerin-, fragrance- and alcohol-free. Lubricant base: silicone. Condoms: page says compatible with natural rubber latex, polyisoprene and polyurethane condoms.', '$22 (size not listed) (brand page, Nov 2026)', 'https://ourkindra.com/cdn/shop/files/Kindra_ProductShot_VLube_Box_2_1.jpg?v=1784212441', 'https://ourkindra.com/products/v-lube?variant=40865341702224', '["comfort","discomfort","fragrance-free"]'::jsonb, '["sexual-health","comfort"]'::jsonb, '["Kindra"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Brand page says ''V Lube is a 510k FDA-cleared medical device'': per the brand; not found in openFDA. No FDA listing found (checked openFDA 2026-11-02).","materials":"Cyclopentasiloxane, Dimethicone and Dimethiconol","allergens":"No allergen list. Page says paraben-, glycerin-, fragrance- and alcohol-free.","sideEffects":"Not recommended for use with silicone toys. FAQ says safe if ingested in small quantities."}'::jsonb, null, null, null, 'brand', 'Product details are Kindra''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Kindra":"https://ourkindra.com/products/v-lube?variant=40865341702224"},"warnings":["Not recommended for use with silicone toys.","FAQ says safe if ingested in small quantities."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://ourkindra.com/products/v-lube?variant=40865341702224","what":"brand product page (linked from the water-based page)"}],"ingredients":"Cyclopentasiloxane, Dimethicone and Dimethiconol","howToUse":{"intro":"Per Kindra''s product page:","steps":["Apply generously to the area you wish to lubricate.","Reapply as needed.","Rinse off with gentle soap and water."],"sourceUrl":"https://ourkindra.com/products/v-lube?variant=40865341702224","sourceLabel":"Kindra: product page"}}'::jsonb),
  ('p-kindra-boric-acid-suppositories', 'Kindra Boric Acid Suppositories', 'Kindra', 'intimate-care', 'physical', 'Vaginal suppositories with 600 mg boric acid, one ingredient. The page says they help restore vaginal pH balance and prevent yeast overgrowth, for people prone to recurring vaginal imbalances. The page pairs them with V Relief Serum for itching, stinging and burning.', '$12.95 sale ($15.95 regular) for 30 suppositories (brand page, Nov 2026)', 'https://ourkindra.com/cdn/shop/files/Kindra_VWell_BoricAcid_9c7bdf56-f3ac-436c-b18e-c78c24f33894.jpg?v=1784210471', 'https://ourkindra.com/products/boric-acid-suppositories-30-counts', '["vaginal-health","discomfort","fragrance-free"]'::jsonb, '["vaginal-health"]'::jsonb, '["Kindra"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02). Page says statements have not been evaluated by the FDA.","materials":"Boric acid, 600 mg per suppository (''one simple ingredient''; full label not shown)","allergens":"None listed. Page says non-GMO, fragrance-free, no artificial dyes or preservatives.","sideEffects":"Not intended to diagnose, treat, cure or prevent any disease (page disclaimer)."}'::jsonb, null, null, null, 'brand', 'Product details are Kindra''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Kindra":"https://ourkindra.com/products/boric-acid-suppositories-30-counts"},"warnings":["Not intended to diagnose, treat, cure or prevent any disease (page disclaimer)."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://ourkindra.com/products/boric-acid-suppositories-30-counts","what":"brand product page"}],"ingredients":"Boric acid, 600 mg per suppository (''one simple ingredient''; full label not shown)","howToUse":{"intro":"Per Kindra''s product page:","steps":["Wash your hands thoroughly.","Insert 1 suppository into the vagina at bedtime for 7 consecutive days, or up to 14 days."],"sourceUrl":"https://ourkindra.com/products/boric-acid-suppositories-30-counts","sourceLabel":"Kindra: product page"}}'::jsonb),
  ('p-womaness-coco-bliss-external-vaginal-moisturizer', 'Womaness Coco Bliss External Vaginal Moisturizer', 'Womaness', 'intimate-care', 'physical', 'A coconut oil-based external vaginal moisturizer for vaginal dryness. The page says it suits menopausal women and doubles as a massage lotion. It is oil-based and not for use with latex condoms.', '$21.99 per pack; 2-pack saves 10%, 3-pack saves 15%; size not listed (brand page, Nov 2026)', 'https://womaness.com/cdn/shop/files/4_11f2ac6f-d515-42fd-83bb-97a06ee2ef71_1024x1024.jpg?v=1776477395', 'https://womaness.com/collections/light-leakage-vaginal-dryness/products/coco-bliss', '["external-only","menopause","discomfort","vaginal-health"]'::jsonb, '["vaginal-health","comfort","menopause"]'::jsonb, '["Womaness"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02). Page says statements have not been evaluated by the FDA.","materials":"Cocos Nucifera (Coconut) Oil, Prunus Amygdalus Dulcis (Sweet Almond) Oil, Butyrospermum Parkii (Shea) Butter, Helianthus Annuus (Sunflower) Seed Wax, Hydrogenated Olive Oil Cetyl Esters, Jojoba Esters, Vanilla Planifolia (Vanilla) Fruit Extract, Acacia Decurrens Flower Wax, Polyglycerin-3","allergens":"Contains nuts (sweet almond oil). FAQ notes some people with tree nut allergies are also allergic to coconut and should ask a doctor first.","sideEffects":"For external use only. Do not use with latex products such as condoms and dental dams; safe with polyurethane products. Contains nuts."}'::jsonb, null, null, null, 'brand', 'Product details are Womaness''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Womaness":"https://womaness.com/collections/light-leakage-vaginal-dryness/products/coco-bliss"},"warnings":["For external use only.","Do not use with latex products such as condoms and dental dams; safe with polyurethane products.","Contains nuts."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://womaness.com/collections/light-leakage-vaginal-dryness/products/coco-bliss","what":"brand product page"}],"ingredients":"Cocos Nucifera (Coconut) Oil, Prunus Amygdalus Dulcis (Sweet Almond) Oil, Butyrospermum Parkii (Shea) Butter, Helianthus Annuus (Sunflower) Seed Wax, Hydrogenated Olive Oil Cetyl Esters, Jojoba Esters, Vanilla Planifolia (Vanilla) Fruit Extract, Acacia Decurrens Flower Wax, Polyglycerin-3","howToUse":{"intro":"Per Womaness''s product page:","steps":["Apply a pea-sized amount to the external vaginal area and gently massage in, for moisture or before intimacy.","Can also be used on dry hands, feet or elbows."],"sourceUrl":"https://womaness.com/collections/light-leakage-vaginal-dryness/products/coco-bliss","sourceLabel":"Womaness: product page"},"optionsNote":"Options: 1 pack, 2 pack, 3 pack."}'::jsonb),
  ('p-womaness-daily-v-soothe', 'Womaness Daily V Soothe', 'Womaness', 'intimate-care', 'physical', 'A water-based external vaginal moisturizer made with hyaluronic acid, for everyday vaginal dryness. The page says it is not sticky, gynecologist tested, and can be used as prep for intimacy. It is vegan and has no estrogen or added hormones.', '$21.99 for 4 fl oz / 118 ml; 2-pack saves 10%, 3-pack saves 15% (brand page, Nov 2026)', 'https://womaness.com/cdn/shop/files/2-DVS-Main_Benefits_b64431af-d863-4c55-af1d-6b41ea8b2513_1024x1024.png?v=1776477327', 'https://womaness.com/collections/light-leakage-vaginal-dryness/products/daily-v-soothe', '["vaginal-health","external-only","hormone-free","vegan","cruelty-free","discomfort"]'::jsonb, '["vaginal-health","comfort"]'::jsonb, '["Womaness"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02). Page says statements have not been evaluated by the FDA.","materials":"Water (Aqua), Glycerin, Propanediol, Hydroxyethylcellulose, Sodium Benzoate, Glycolic Acid, Sodium Hyaluronate","allergens":"No allergen statement. Page says dermatologist and allergy tested; free of animal-derived ingredients, parabens, phthalates, sulfates, artificial colors, formaldehyde, mineral oils; gluten-free and soy-free.","sideEffects":"Page says it is condom compatible (no silicone or oil) but may need an added lubricant for comfort. Ask your doctor for lubricant recommendations."}'::jsonb, null, null, null, 'brand', 'Product details are Womaness''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Womaness":"https://womaness.com/collections/light-leakage-vaginal-dryness/products/daily-v-soothe"},"warnings":["Page says it is condom compatible (no silicone or oil) but may need an added lubricant for comfort.","Ask your doctor for lubricant recommendations."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://womaness.com/collections/light-leakage-vaginal-dryness/products/daily-v-soothe","what":"brand product page"}],"ingredients":"Water (Aqua), Glycerin, Propanediol, Hydroxyethylcellulose, Sodium Benzoate, Glycolic Acid, Sodium Hyaluronate","howToUse":{"intro":"Per Womaness''s product page:","steps":["Apply a pea-sized amount to the external vaginal area and gently massage in.","FAQ says it can be used daily, or several times a day."],"sourceUrl":"https://womaness.com/collections/light-leakage-vaginal-dryness/products/daily-v-soothe","sourceLabel":"Womaness: product page"},"optionsNote":"Options: 4 fl oz single, 2 pack, 3 pack."}'::jsonb),
  ('p-womaness-melt-for-you-vaginal-inserts', 'Womaness Melt For You Vaginal Inserts', 'Womaness', 'intimate-care', 'physical', 'Hormone-free melting vaginal inserts that release hyaluronic acid, for vaginal dryness, irritation or discomfort during intimacy. The page says they may be used with HRT. Seven inserts, used every 2 to 3 days.', '$27 for 7 inserts (brand page, Nov 2026)', 'http://womaness.com/cdn/shop/files/Whattoexpect-video3-web2_1024x1024.gif?v=1776173017', 'https://womaness.com/collections/light-leakage-vaginal-dryness/products/melt-for-you', '["vaginal-health","hormone-free","vegan","discomfort"]'::jsonb, '["vaginal-health","comfort"]'::jsonb, '["Womaness"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02). Page says statements have not been evaluated by the FDA.","materials":"Sodium hyaluronate, cocoa butter, lactic acid, hard fat (semi-synthetic glycerides)","allergens":"Contains cocoa butter: avoid with cocoa or chocolate allergy. Page says dermatologist and allergy tested, vegan, gluten-free, soy-free.","sideEffects":"For vaginal use only; not for oral use. Do not use at the same time as a tampon. Patch-test on the inner forearm if you have sensitive tissue or a known ingredient allergy; stop if irritation occurs. Not compatible with latex or polyisoprene condoms, dental dams or diaphragms; page suggests polyurethane condoms. Check with your provider first if you use prescription vaginal medications or hormone treatments."}'::jsonb, null, null, null, 'brand', 'Product details are Womaness''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Womaness":"https://womaness.com/collections/light-leakage-vaginal-dryness/products/melt-for-you"},"warnings":["For vaginal use only; not for oral use.","Do not use at the same time as a tampon.","Patch-test on the inner forearm if you have sensitive tissue or a known ingredient allergy; stop if irritation occurs.","Not compatible with latex or polyisoprene condoms, dental dams or diaphragms; page suggests polyurethane condoms.","Check with your provider first if you use prescription vaginal medications or hormone treatments."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://womaness.com/collections/light-leakage-vaginal-dryness/products/melt-for-you","what":"brand product page"}],"ingredients":"Sodium hyaluronate, cocoa butter, lactic acid, hard fat (semi-synthetic glycerides)","howToUse":{"intro":"Per Womaness''s product page:","steps":["Wash hands and insert one insert with a clean finger as far as comfortable, ideally at bedtime.","Adults: one suppository, preferably at night, 2 to 3 days per week.","Wear a pantyliner.","Store in a cool, dry place; refrigerate in warm climates if needed."],"sourceUrl":"https://womaness.com/collections/light-leakage-vaginal-dryness/products/melt-for-you","sourceLabel":"Womaness: product page"}}'::jsonb),
  ('p-stripes-vag-of-honor-vaginal-moisturizer', 'Stripes Vag of Honor Vaginal Moisturizer', 'Stripes', 'intimate-care', 'physical', 'A hormone-free gel moisturizer for external intimate and vulvar areas, with ectoine, hyaluronic acid and plant-based glycogen. The page lists vaginal dryness, irritation and atrophy, and centers on menopause. It is vegan, fragrance-free and Leaping Bunny cruelty-free.', '$50 for 50 ml / 1.7 fl oz ($42.50 subscribe) (brand page, Nov 2026)', 'https://stripesbeauty.com/cdn/shop/files/Group56482_b08a2ef4-de5c-48d3-8800-ab45b7263d3a.png?v=1791282145&width=2048', 'https://stripesbeauty.com/products/vag-of-honor', '["external-only","menopause","vaginal-health","hormone-free","vegan","cruelty-free","fragrance-free"]'::jsonb, '["vaginal-health","menopause","comfort"]'::jsonb, '["Stripes"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02).","materials":"Water/Aqua/Eau, Glycogen, Xanthan Gum, Ectoin (Ectoine), Squalane, Sodium Hyaluronate, Lactic Acid, Carrageenan, Potassium Sorbate, Sodium Benzoate","allergens":"No allergen list. Page says hypoallergenic, fragrance-free, silicone-, sulfate- and paraben-free."}'::jsonb, null, null, null, 'brand', 'Product details are Stripes''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Stripes":"https://stripesbeauty.com/products/vag-of-honor"},"warnings":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://stripesbeauty.com/products/vag-of-honor","what":"brand product page"},{"url":"https://stripesbeauty.com/","what":"homepage product list"}],"ingredients":"Water/Aqua/Eau, Glycogen, Xanthan Gum, Ectoin (Ectoine), Squalane, Sodium Hyaluronate, Lactic Acid, Carrageenan, Potassium Sorbate, Sodium Benzoate","howToUse":{"intro":"Per Stripes''s product page:","steps":["Apply 1-2 pumps to fingers and massage onto external intimate areas daily."],"sourceUrl":"https://stripesbeauty.com/products/vag-of-honor","sourceLabel":"Stripes: product page"}}'::jsonb),
  ('p-stripes-oh-my-glide-intimate-play-oil', 'Stripes Oh My Glide Intimate Play Oil', 'Stripes', 'intimate-care', 'physical', 'A moisturizing vaginal oil for use in the bedroom and beyond. The page says it lubricates, restores moisture and eases discomfort linked to hormonal changes. Lubricant base: oil (page lists only oils, butter and wax; it does not use the word ''oil-based''). Condoms: page says do not use with latex condoms or sex toys.', '$45 for 100 ml / 3.3 fl oz ($38 subscribe) (brand page, Nov 2026)', 'https://stripesbeauty.com/cdn/shop/files/VAG1.webp?v=1777817975&width=1080', 'https://stripesbeauty.com/products/oh-my-glide', '["comfort","discomfort","hormone-free","fragrance-free"]'::jsonb, '["sexual-health","comfort"]'::jsonb, '["Stripes"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02).","materials":"Citrus Paradisi (Grapefruit) Seed Oil, Cocos Nucifera (Coconut) Oil, Butyrospermum Parkii (Shea) Butter, Ricinus Communis (Castor) Seed Oil, Persea Gratissima (Avocado) Oil, Squalane, Hydrogenated Castor Oil, Copernicia Cerifera (Carnauba) Wax, Bisabolol","allergens":"No allergen statement. Page says fragrance-free and hypoallergenic; contains coconut, shea and avocado.","sideEffects":"Do not use with latex products, such as condoms or sex toys."}'::jsonb, null, null, null, 'brand', 'Product details are Stripes''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Stripes":"https://stripesbeauty.com/products/oh-my-glide"},"warnings":["Do not use with latex products, such as condoms or sex toys."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://stripesbeauty.com/products/oh-my-glide","what":"brand product page"}],"ingredients":"Citrus Paradisi (Grapefruit) Seed Oil, Cocos Nucifera (Coconut) Oil, Butyrospermum Parkii (Shea) Butter, Ricinus Communis (Castor) Seed Oil, Persea Gratissima (Avocado) Oil, Squalane, Hydrogenated Castor Oil, Copernicia Cerifera (Carnauba) Wax, Bisabolol","howToUse":{"intro":"Per Stripes''s product page:","steps":["Apply a generous amount to lubricate, or when you need extra moisture."],"sourceUrl":"https://stripesbeauty.com/products/oh-my-glide","sourceLabel":"Stripes: product page"}}'::jsonb),
  ('p-bonafide-revaree', 'Bonafide Revaree', 'Bonafide', 'intimate-care', 'physical', 'A hormone-free vaginal insert with 5 mg hyaluronic acid for vaginal dryness, discomfort and painful sex. The page discusses menopause-related estrogen decline and notes dryness can also come from lactation, birth control pills, other medications and smoking.', '$63 for 30 inserts (3-month supply) one-time; subscriptions $37-$47/mo (brand page, Nov 2026)', 'https://hellobonafide.com/cdn/shop/files/Bonafide__REV30DAYSTOCKB_Shopify_Cart_2.png?v=1756823829', 'https://hellobonafide.com/products/revaree', '["vaginal-health","menopause","hormone-free","discomfort"]'::jsonb, '["vaginal-health","menopause","comfort"]'::jsonb, '["Bonafide"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-registered/listed (product code NUC, Class 2). Brand says ''cleared by the FDA as a Class II Medical Device'': per the brand; no 510(k) found in openFDA under the Revaree name (only Revaree Plus, K213220).","materials":"Hyaluronic acid 5 mg per insert. Other ingredients: semi-synthetic glycerides and sodium salt.","allergens":"No allergen list. Page says free of hormones, parabens, soy, gluten and GMOs.","sideEffects":"Not a contraceptive or spermicide. Not compatible with condoms."}'::jsonb, null, null, null, 'brand', 'Product details are Bonafide''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Bonafide":"https://hellobonafide.com/products/revaree"},"warnings":["Not a contraceptive or spermicide.","Not compatible with condoms."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://hellobonafide.com/products/revaree","what":"brand product page"},{"url":"https://api.fda.gov/device/registrationlisting.json?search=proprietary_name:\"Revaree\"&limit=10","what":"openFDA registration"},{"url":"https://api.fda.gov/device/510k.json?search=device_name:\"Revaree\"&limit=10","what":"openFDA 510(k)"}],"ingredients":"Hyaluronic acid 5 mg per insert. Other ingredients: semi-synthetic glycerides and sodium salt.","howToUse":{"intro":"Per Bonafide''s product page:","steps":["Use at bedtime, one insert every 2-3 nights, or as directed by your doctor.","Lie down and remove the insert by pulling the two flaps of the plastic strip.","Lying on your back with knees bent, push it into the vagina as far as comfortable.","Stay lying down for 30 minutes."],"sourceUrl":"https://hellobonafide.com/products/revaree","sourceLabel":"Bonafide: product page"}}'::jsonb),
  ('p-bonafide-revaree-plus', 'Bonafide Revaree Plus', 'Bonafide', 'intimate-care', 'physical', 'A hormone-free vaginal insert with 10 mg hyaluronic acid and sweet almond oil, for any woman with vaginal dryness or pain during intimacy. It is Bonafide''s extra-strength version of Revaree, with twice the hyaluronic acid.', '$65 for 30 inserts (3-month supply) one-time; subscriptions $41-$52/mo (brand page, Nov 2026)', 'https://hellobonafide.com/cdn/shop/files/Bonafide_REVPLUS30DAYSTOCKB_Shopify_Cart_ed50328f-e192-4596-9def-76168ff206c1.png?v=1756823758', 'https://hellobonafide.com/products/revaree-plus', '["vaginal-health","menopause","hormone-free","discomfort"]'::jsonb, '["vaginal-health","sexual-health","comfort"]'::jsonb, '["Bonafide"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"510(k)-cleared (K213220) and FDA-registered/listed (product code NUC, Class 2)","materials":"10 mg hyaluronic acid sodium salt, sweet almond oil, semi-synthetic glycerides","allergens":"Contains refined sweet almond oil; page advises avoiding it with almond sensitivity or allergy (use Revaree instead). Free of hormones, parabens, soy, gluten and GMOs.","sideEffects":"Not compatible with natural rubber latex, polyurethane or polyisoprene condoms. Avoid with almond allergy."}'::jsonb, null, null, null, 'brand', 'Product details are Bonafide''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Bonafide":"https://hellobonafide.com/products/revaree-plus"},"warnings":["Not compatible with natural rubber latex, polyurethane or polyisoprene condoms.","Avoid with almond allergy."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://hellobonafide.com/products/revaree-plus","what":"brand product page"},{"url":"https://api.fda.gov/device/510k.json?search=device_name:\"Revaree\"&limit=10","what":"openFDA 510(k) K213220"}],"ingredients":"10 mg hyaluronic acid sodium salt, sweet almond oil, semi-synthetic glycerides","howToUse":{"intro":"Per Bonafide''s product page:","steps":["Insert while lying down, preferably at bedtime, then stay lying down about 30 minutes.","Repeat every 2-3 nights or as your doctor directs (FAQ says every three days)."],"sourceUrl":"https://hellobonafide.com/products/revaree-plus","sourceLabel":"Bonafide: product page"}}'::jsonb),
  ('p-bonafide-clairvee-vaginal-pre-probiotic', 'Bonafide Clairvee Vaginal Pre + Probiotic', 'Bonafide', 'supplement', 'physical', 'An oral pre+probiotic capsule for the vaginal microbiome, taken 15 days each month. The page says it is clinically tested to reduce vaginal odor, itching and discharge, and is for any woman wanting to support vaginal microbiome balance. It is taken by mouth, not inserted.', '$55 for 45 capsules (3-month supply) one-time; $35-$39/mo subscription (brand page, Nov 2026)', 'https://hellobonafide.com/cdn/shop/files/Clairvee_1Month.png?v=1759871399', 'https://hellobonafide.com/products/clairvee', '["probiotic","supplement","vaginal-health","hormone-free"]'::jsonb, '["vaginal-health","supplement"]'::jsonb, '["Bonafide"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","allergens":"Contains milk (lactoferrin is milk-derived). Free of hormones, parabens, soy, gluten and GMOs.","sideEffects":"Talk to a healthcare practitioner first if you have lactose intolerance concerns (lactoferrin is milk-derived). Not intended to diagnose, treat, cure or prevent any disease."}'::jsonb, null, null, null, 'brand', 'Product details are Bonafide''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Bonafide":"https://hellobonafide.com/products/clairvee"},"warnings":["Talk to a healthcare practitioner first if you have lactose intolerance concerns (lactoferrin is milk-derived).","Not intended to diagnose, treat, cure or prevent any disease."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://hellobonafide.com/products/clairvee","what":"brand product page incl. Supplement Facts"}],"ingredients":"Per 1 capsule: Lactobacillus acidophilus 4 billion CFU; Lactobacillus rhamnosus 1 billion CFU; Lactoferrin 50 mg; Folate (as L-methylfolate monosodium) 400 mcg. Other ingredients: microcrystalline cellulose, capsule (hypromellose, pectin, glycerol), magnesium stearate, silicon dioxide.","howToUse":{"intro":"Per Bonafide''s product page:","steps":["Take one capsule by mouth once daily for 15 consecutive days each month.","Do not insert into the vagina."],"sourceUrl":"https://hellobonafide.com/products/clairvee","sourceLabel":"Bonafide: product page"}}'::jsonb),
  ('p-vella-meltwater-vaginal-emollient', 'Vella Meltwater Vaginal Emollient', 'Vella', 'intimate-care', 'physical', 'A water-based moisturizer with hyaluronic acid and aloe vera for menopause-related dryness, applied to external intimate areas. The page says it suits anyone who needs extra moisture. Base: water. Condoms: FAQ says it is condom compatible.', '$28 for 50 ml / 1.7 fl oz ($23.80 subscribe) (brand page, Nov 2026)', 'https://vellabio.com/cdn/shop/files/Meltwater_ef485c44-b56c-4b00-b4c8-baac41af27bb.png?v=1782850866', 'https://vellabio.com/products/water-based-lube', '["vaginal-health","menopause","external-only","hormone-free","herbal"]'::jsonb, '["vaginal-health","menopause","comfort"]'::jsonb, '["Vella"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02).","materials":"Aqua (Water), Propylene Glycol, Glycerin, Hydroxyethyl Cellulose, Aloe Barbadensis (Aloe Vera) Leaf Juice Powder, Propanediol, Aqua (and) Sodium Hyaluronate, Glycerin (and) Aqua (and) Vitex Agnus-Castus (Chasteberry) Extract, Lactic Acid, Sodium Benzoate, Potassium Sorbate, Hydrastis Canadensis (Goldenseal Root) Extract","allergens":"No allergen statement. Contains chasteberry, goldenseal root and aloe."}'::jsonb, null, null, null, 'brand', 'Product details are Vella''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Vella":"https://vellabio.com/products/water-based-lube"},"warnings":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://vellabio.com/products/water-based-lube","what":"brand product page"}],"ingredients":"Aqua (Water), Propylene Glycol, Glycerin, Hydroxyethyl Cellulose, Aloe Barbadensis (Aloe Vera) Leaf Juice Powder, Propanediol, Aqua (and) Sodium Hyaluronate, Glycerin (and) Aqua (and) Vitex Agnus-Castus (Chasteberry) Extract, Lactic Acid, Sodium Benzoate, Potassium Sorbate, Hydrastis Canadensis (Goldenseal Root) Extract","howToUse":{"intro":"Per Vella''s product page:","steps":["Apply 1-2 pumps to fingers and gently massage onto external intimate areas daily."],"sourceUrl":"https://vellabio.com/products/water-based-lube","sourceLabel":"Vella: product page"}}'::jsonb),
  ('p-vella-everslide-personal-lubricant', 'Vella Everslide Personal Lubricant', 'Vella', 'intimate-care', 'physical', 'A silicone-based personal lubricant with plant squalane, sea buckthorn oil and vitamin E, made to moisturize and add comfort during sex. Lubricant base: silicone (per FAQ). Condoms: FAQ says tested with latex and polyisoprene condoms, not compatible with polyurethane (another FAQ answer contradicts this).', '$24 ($20.40 subscribe); size not listed (brand page, Nov 2026)', 'https://vellabio.com/cdn/shop/files/Everslide.png?v=1782849943', 'https://vellabio.com/products/lube-for-women', '["comfort","discomfort","skin"]'::jsonb, '["sexual-health","comfort"]'::jsonb, '["Vella"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"510(k)-cleared (K260117)","materials":"Dimethicone (and) Dimethiconol, Dimethicone, Squalane, Tocopheryl Acetate (Vitamin E), Hippophae Rhamnoides Seed Oil, Lavandula Angustifolia Oil","allergens":"No allergen statement. Contains lavender oil despite ''scentless'' claim.","sideEffects":"Not compatible with polyurethane condoms (per FAQ)."}'::jsonb, null, null, null, 'brand', 'Product details are Vella''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Vella":"https://vellabio.com/products/lube-for-women"},"warnings":["Not compatible with polyurethane condoms (per FAQ)."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://vellabio.com/products/lube-for-women","what":"brand product page"}],"ingredients":"Dimethicone (and) Dimethiconol, Dimethicone, Squalane, Tocopheryl Acetate (Vitamin E), Hippophae Rhamnoides Seed Oil, Lavandula Angustifolia Oil","howToUse":{"intro":"Per Vella''s product page:","steps":["Pump and apply anywhere on the body where lubrication is wanted; a small amount goes a long way."],"sourceUrl":"https://vellabio.com/products/lube-for-women","sourceLabel":"Vella: product page"}}'::jsonb),
  ('p-vella-ebbtide-vaginal-inserts', 'Vella Ebbtide Vaginal Inserts', 'Vella', 'cramp-relief', 'physical', 'A melting vaginal insert with 75 mg CBD and 25 mg CBDA per insert, to ease menstrual cramps and pelvic tension. The page says it is for women with period cramps, from first cycles through perimenopause, including those wanting less oral pain medication. It is not a lubricant and is not compatible with condoms.', '$40 one-time or $32 subscribe; page does not say whether this is the 8-pack or 4-pack (brand page, Nov 2026)', 'https://vellabio.com/cdn/shop/files/Ebbtide.png?v=1782849944', 'https://vellabio.com/products/ebbtide', '["cramps","discomfort","herbal"]'::jsonb, '["cramp-relief"]'::jsonb, '["Vella"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02).","materials":"Saturated Fatty Acids Glycerides C12-C18, Cocos Nucifera (Coconut) Oil, Cannabidiol, Hydrogenated Palm/Palm Kernel Oil PEG-6 Esters, Cannabidiolic Acid, Tocopherol. 75 mg CBD and 25 mg CBDA per insert; less than 0.03% THC.","allergens":"Do not use with an allergy to coconut, cannabinoids or cannabis.","sideEffects":"Not compatible with condoms. Mild discomfort on insertion may occur; see a physician if it lasts past 30 minutes and is not relieved by an oral pain reliever. Do not use if pregnant or breastfeeding. Contains cannabinoids."}'::jsonb, null, null, null, 'brand', 'Product details are Vella''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Vella":"https://vellabio.com/products/ebbtide"},"warnings":["Not compatible with condoms.","Mild discomfort on insertion may occur; see a physician if it lasts past 30 minutes and is not relieved by an oral pain reliever.","Do not use if pregnant or breastfeeding.","Contains cannabinoids."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://vellabio.com/products/ebbtide","what":"brand product page"}],"ingredients":"Saturated Fatty Acids Glycerides C12-C18, Cocos Nucifera (Coconut) Oil, Cannabidiol, Hydrogenated Palm/Palm Kernel Oil PEG-6 Esters, Cannabidiolic Acid, Tocopherol. 75 mg CBD and 25 mg CBDA per insert; less than 0.03% THC.","howToUse":{"intro":"Per Vella''s product page:","steps":["Start at the first sign of cramps or bleeding; continue daily as needed.","Use 1-2 inserts in 24 hours, at least 4 hours apart.","Remove tampons, cups or discs first.","Insert reclined with knees bent and hips elevated; let it dissolve fully.","Night use recommended; wear a pad or liner for leakage.","Store in a cool, dry place."],"sourceUrl":"https://vellabio.com/products/ebbtide","sourceLabel":"Vella: product page"},"optionsNote":"Options: 8-pack, 4-pack.","hiddenReason":"Not every fact is sourced yet: Price per pack size unclear.; Sheet groups it with lubes; it is a CBD cramp-relief insert.; Page ''clinically proven'' claims cite studies not read here.; Tag ''herbal'' is a judgment (plant-derived CBD); review."}'::jsonb),
  ('p-o-positiv-uro-vaginal-probiotic-capsules', 'O Positiv URO Vaginal Probiotic Capsules', 'O Positiv', 'supplement', 'physical', 'An oral probiotic capsule with a 5 billion CFU four-strain Lactobacillus blend plus XOS prebiotic, for healthy vaginal odor, pH and yeast balance. The page says it is for women 18 and up who want to maintain healthy vaginal bacteria, including those concerned about scent or prone to imbalance.', '$31.99 for 60 capsules (30 servings) one-time; $26.99 on monthly delivery (brand page, Nov 2026)', null, 'https://opositiv.com/products/uro-vaginal-probiotic-capsules', '["probiotic","supplement","vaginal-health"]'::jsonb, '["vaginal-health","supplement"]'::jsonb, '["O Positiv"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","sideEffects":"Consult your physician before use if you have a medical condition or take medications. Do not use if cap seal is broken or missing. Keep out of reach of children. For ages 18 and up."}'::jsonb, null, null, null, 'brand', 'Product details are O Positiv''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"O Positiv":"https://opositiv.com/products/uro-vaginal-probiotic-capsules"},"warnings":["Consult your physician before use if you have a medical condition or take medications.","Do not use if cap seal is broken or missing.","Keep out of reach of children.","For ages 18 and up."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://opositiv.com/products/uro-vaginal-probiotic-capsules","what":"brand product page incl. Supplement Facts"},{"url":"https://opositiv.com/","what":"homepage product list"}],"ingredients":"Serving size 2 capsules; 30 servings. V-Positiv Probiotic Blend 50 mg (5 Billion CFUs): Lactobacillus acidophilus, Lactobacillus rhamnosus, Lactobacillus reuteri, Lactobacillus fermentum (per-strain amounts not listed). Xylooligosaccharides (XOS) 400 mg. Other ingredients: Maltodextrin, Cellulose (Vegetarian Capsule), Natural Color.","howToUse":{"intro":"Per O Positiv''s product page:","steps":["Take 2 capsules once daily with water.","Store in a cool, dry place.","Page says fully effective about 8 weeks in."],"sourceUrl":"https://opositiv.com/products/uro-vaginal-probiotic-capsules","sourceLabel":"O Positiv: product page"},"hiddenReason":"Not every fact is sourced yet: no product photo yet (the brand page shows only a generic image); Pregnancy, breastfeeding, allergens not stated.; og:image is a generic site-wide ''Preview-Photo.jpg'' shared by all O Positiv pages; set to null.; Gummy format exists (separate product per rules); not researched."}'::jsonb),
  ('p-o-positiv-uro-boric-acid-vaginal-suppository', 'O Positiv URO Boric Acid Vaginal Suppository', 'O Positiv', 'intimate-care', 'physical', 'A vegan vaginal suppository with 600 mg boric acid plus aloe and lactic acid, for odor control and intimate care. The page says it is for people concerned about vaginal odor, discomfort or imbalance. It is for short-term use, up to 12 days.', '$22.99 for 12 suppositories one-time; $18.99 on monthly subscription (brand page, Nov 2026)', null, 'https://opositiv.com/products/uro-boric-acid-suppositories', '["vaginal-health","vegan","discomfort"]'::jsonb, '["vaginal-health"]'::jsonb, '["O Positiv"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02). Page says statements have not been evaluated by the FDA.","materials":"C10-18 Triglycerides, Boric Acid, Aloe Barbadensis Leaf Juice, Lactic Acid (FAQ: 600 mg boric acid per suppository; other amounts not listed)","allergens":"Page says formulated without latex; no other allergens listed.","sideEffects":"Not for oral use. If swallowed, get medical help or contact Poison Control right away. Do not use if pregnant or breastfeeding. Not compatible with latex condoms; avoid intercourse for at least 24 hours after use. Not for long-term daily use. Stop and see a healthcare professional if symptoms last beyond 2 weeks, worsen, or cause irritation or burning. For ages 18 and up. Do not use if seal is broken; keep out of reach of children."}'::jsonb, null, null, null, 'brand', 'Product details are O Positiv''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"O Positiv":"https://opositiv.com/products/uro-boric-acid-suppositories"},"warnings":["Not for oral use. If swallowed, get medical help or contact Poison Control right away.","Do not use if pregnant or breastfeeding.","Not compatible with latex condoms; avoid intercourse for at least 24 hours after use.","Not for long-term daily use.","Stop and see a healthcare professional if symptoms last beyond 2 weeks, worsen, or cause irritation or burning.","For ages 18 and up.","Do not use if seal is broken; keep out of reach of children."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://opositiv.com/products/uro-boric-acid-suppositories","what":"brand product page (linked from the wash page)"}],"ingredients":"C10-18 Triglycerides, Boric Acid, Aloe Barbadensis Leaf Juice, Lactic Acid (FAQ: 600 mg boric acid per suppository; other amounts not listed)","howToUse":{"intro":"Per O Positiv''s product page:","steps":["Wash hands before and after use.","Insert one suppository into the vagina once daily, preferably at bedtime, for up to 12 days.","Expect some discharge; use a liner.","Wait until the end, or near the end, of your period before starting."],"sourceUrl":"https://opositiv.com/products/uro-boric-acid-suppositories","sourceLabel":"O Positiv: product page"},"hiddenReason":"Not every fact is sourced yet: no product photo yet (the brand page shows only a generic image); Page does not mention BV; sheet''s ''BV'' use not sourced.; og:image is a generic site-wide preview photo; set to null.; Amazon listing could not be read (WebFetch blocked by amazon.com robots); ASIN not verified."}'::jsonb),
  ('p-o-positiv-uro-ph-balanced-probiotic-intimate-was', 'O Positiv URO pH-Balanced Probiotic Intimate Wash', 'O Positiv', 'intimate-care', 'physical', 'A pH-balanced, soap-free probiotic body wash that is safe on the vulva, made for daily odor control. The page says it is dermatologist-tested for sensitive skin and is for ages 18 and up. It is for external use only.', '$17.99 for 6.75 fl oz / 200 ml one-time; $14.99 on monthly delivery (brand page, Nov 2026)', null, 'https://opositiv.com/products/uro-ph-balanced-probiotic-wash-subscription', '["external-only","vaginal-health","ph-neutral","vegan","skin"]'::jsonb, '["vaginal-health","skin-hair"]'::jsonb, '["O Positiv"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"No FDA listing found (checked openFDA 2026-11-02). Page says statements have not been evaluated by the FDA.","materials":"Full lists not captured. Both scents include Water, Sodium Cocoyl Isethionate, Cocamidopropyl Betaine, Lactobacillus Ferment, Lactic Acid, Glycerin, Sodium Hyaluronate, Aloe Barbadensis Leaf Juice, Avena Sativa (Oat) Bran Extract, among others. Eucalyptus & Lavender adds lavender and eucalyptus leaf oils; Vanilla & Honey lists Fragrance (Parfum).","allergens":"Not listed. Page says hypoallergenic, free of parabens, sulfates, phthalates, aluminum, baking soda and artificial fragrances and dyes (but Vanilla & Honey lists Fragrance).","sideEffects":"For external use only; do not use inside the vagina. Avoid contact with eyes. If irritation or allergic reaction occurs, rinse off and stop use; see a healthcare practitioner if it continues. Not edible."}'::jsonb, null, null, null, 'brand', 'Product details are O Positiv''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"O Positiv":"https://opositiv.com/products/uro-ph-balanced-probiotic-wash-subscription"},"warnings":["For external use only; do not use inside the vagina.","Avoid contact wit