  ('p-bonafide-relizen', 'Bonafide Relizen', 'Bonafide', 'menopause', 'physical', 'Relizen is a plant-based, hormone-free tablet made with Swedish flower pollen extract. It is intended for women experiencing hot flashes and night sweats associated with menopause.', '$58 single box (+$5 shipping); subscribe from $42/mo monthly, $114 per quarter, or $198 semiannually (brand page, Nov 2026)', 'https://hellobonafide.com/cdn/shop/files/Bonafide__RLZ30DAYSTOCKB_Shopify_Cart_2.png?v=1756823835', 'https://hellobonafide.com/products/relizen', '["menopause","hormone-free","non-hormonal","supplement","herbal","sleep"]'::jsonb, '["menopause","supplement"]'::jsonb, '["Bonafide"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","materials":"Amount per two tablets: Purified Cytoplasmic Blend (proprietary Swedish Flower pollen extract (Sérélys) in the form of Pollen + Pistil Extract PI-82, and Pollen Extract GC-FEM) [amount not shown on page]. Other ingredients: Isomalt, Maltodextrin, Microcrystalline cellulose, Acacia, Magnesium Stearate, Vitamin E (as d-α-tocopheryl succinate), Hydroxypropyl methylcellulose (alternatively HPMC), Silica, Polysorbate.","allergens":"No allergen statement on page. Free-from claim: \"All of our products are free of hormones, parabens, soy, gluten, and GMOs.\"","sideEffects":"If you have specific concerns, we recommend that you speak with your doctor. These statements have not been evaluated by the Food and Drug Administration."}'::jsonb, null, null, null, 'brand', 'Product details are Bonafide''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Bonafide":"https://hellobonafide.com/products/relizen"},"warnings":["If you have specific concerns, we recommend that you speak with your doctor.","These statements have not been evaluated by the Food and Drug Administration."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://hellobonafide.com/products/relizen","what":"Product page: name, prices, ingredients, directions, free-from claims, og:image"}],"ingredients":"Amount per two tablets: Purified Cytoplasmic Blend (proprietary Swedish Flower pollen extract (Sérélys) in the form of Pollen + Pistil Extract PI-82, and Pollen Extract GC-FEM) [amount not shown on page]. Other ingredients: Isomalt, Maltodextrin, Microcrystalline cellulose, Acacia, Magnesium Stearate, Vitamin E (as d-α-tocopheryl succinate), Hydroxypropyl methylcellulose (alternatively HPMC), Silica, Polysorbate.","howToUse":{"intro":"Per Bonafide''s product page:","steps":["Take two tablets once per day, with or without food."],"sourceUrl":"https://hellobonafide.com/products/relizen","sourceLabel":"Bonafide: product page"},"hiddenReason":"Not every fact is sourced yet: Supplement Facts amount for the pollen extract blend not shown on page; No allergen statement (contains pollen extract; page does not address pollen allergy); No pregnancy, breastfeeding or medication warnings on page; Bonafide page heading reads ''180 tablets | 3-month supply'' while the single-box price sits beside it; tablet count per single box is not clearly stated"}'::jsonb),
  ('p-bonafide-thermella', 'Bonafide Thermella', 'Bonafide', 'menopause', 'physical', 'Thermella is a hormone-free tablet that targets hot flashes and night sweats. It is intended for women experiencing hot flashes or night sweats associated with menopause.', '$60 single box (+$5 shipping); subscribe from $45/mo monthly, $120 per quarter, or $210 semiannually (brand page, Nov 2026)', 'http://hellobonafide.com/cdn/shop/files/Bonafide_THE30DAYSTOCKB_Shopify_Cart_1.png?v=1756823886', 'https://hellobonafide.com/products/thermella', '["menopause","hormone-free","non-hormonal","supplement","herbal","sleep"]'::jsonb, '["menopause","supplement"]'::jsonb, '["Bonafide"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","materials":"Amount per two tablets: Longvida® Curcumin Extract 600 mg; Decaffeinated± Green Tea Extract 150 mg; Spirulina Extract 85 mg. ± Contains less than 5 mg of naturally occurring caffeine. Other ingredients: Microcrystalline cellulose, stearic acid, maltodextrin, lecithin, coating (rice starch (color), isomalt, hydroxypropyl methylcellulose, medium chain triglycerides, color (spirulina, caramel, carmine), d-trehalose, croscarmellose sodium, silica, ascorbyl palmitate, magnesium stearate.","allergens":"No allergen statement on page. Free-from claim: \"All of our products are free of hormones, parabens, soy, gluten, and GMOs.\" Ingredient list includes lecithin (source not stated) and carmine color.","sideEffects":"Contains less than 5 mg of naturally occurring caffeine. Every woman is different and if you have specific concerns, you should speak with your doctor or healthcare practitioner. These statements have not been evaluated by the Food and Drug Administration."}'::jsonb, null, null, null, 'brand', 'Product details are Bonafide''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Bonafide":"https://hellobonafide.com/products/thermella"},"warnings":["Contains less than 5 mg of naturally occurring caffeine.","Every woman is different and if you have specific concerns, you should speak with your doctor or healthcare practitioner.","These statements have not been evaluated by the Food and Drug Administration."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://hellobonafide.com/products/thermella","what":"Product page: name, prices, Supplement Facts, other ingredients, directions, og:image"}],"ingredients":"Amount per two tablets: Longvida® Curcumin Extract 600 mg; Decaffeinated± Green Tea Extract 150 mg; Spirulina Extract 85 mg. ± Contains less than 5 mg of naturally occurring caffeine. Other ingredients: Microcrystalline cellulose, stearic acid, maltodextrin, lecithin, coating (rice starch (color), isomalt, hydroxypropyl methylcellulose, medium chain triglycerides, color (spirulina, caramel, carmine), d-trehalose, croscarmellose sodium, silica, ascorbyl palmitate, magnesium stearate.","howToUse":{"intro":"Per Bonafide''s product page:","steps":["Take two tablets once per day, with or without food."],"sourceUrl":"https://hellobonafide.com/products/thermella","sourceLabel":"Bonafide: product page"}}'::jsonb),
  ('p-bonafide-serenol', 'Bonafide Serenol', 'Bonafide', 'supplement', 'physical', 'Serenol is a hormone-free tablet with Swedish flower pollen extract, royal jelly and chromium. It is intended for women with emotional symptoms from hormonal changes like PMS and menopause, including irritability, mood fluctuations and uneasiness.', '$63 single box (+$5 shipping); subscribe from $48/mo monthly, $129 per quarter, or $222 semiannually (brand page, Nov 2026)', 'http://hellobonafide.com/cdn/shop/files/Bonafide_SER30DAYSTOCKB_Shopify_Cart_1.png?v=1756823592', 'https://hellobonafide.com/products/serenol', '["pms","menopause","perimenopause","hormone-free","non-hormonal","supplement","stress","bloating"]'::jsonb, '["mental-health","menopause","supplement"]'::jsonb, '["Bonafide"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","allergens":"\"This product contains royal jelly.\" \"Avoid Serenol if you are allergic to bees or bee products.\" Free-from claim: free of hormones, parabens, soy, gluten, and GMOs.","sideEffects":"Avoid Serenol if you are allergic to bees or bee products. If you have specific concerns, we recommend that you speak with your doctor. These statements have not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure, or prevent any disease."}'::jsonb, null, null, null, 'brand', 'Product details are Bonafide''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Bonafide":"https://hellobonafide.com/products/serenol"},"warnings":["Avoid Serenol if you are allergic to bees or bee products.","If you have specific concerns, we recommend that you speak with your doctor.","These statements have not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure, or prevent any disease."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://hellobonafide.com/products/serenol","what":"Product page: name, prices, ingredients, royal jelly allergen statement, directions, og:image"}],"ingredients":"Amount per two tablets [amounts not shown on page]: Chromium (as Chromium Picolinate); Purified Cytoplasmic Blend (proprietary Swedish flower pollen extract (Sérélys) in the form of Pollen + Pistil Extract PI-82, and Pollen Extract GC-FEM); Royal Jelly. Other ingredients: Maltodextrin, Calcium Carbonate, Acacia, Isomalt, d-α-tocopheryl succinate (antioxidant), Stearic Acid, Croscarmellose Sodium, Magnesium Stearate, Hydroxypropyl Methylcellulose (alternatively HPMC), Silica, Polysorbate.","howToUse":{"intro":"Per Bonafide''s product page:","steps":["Take two tablets once per day, with or without food."],"sourceUrl":"https://hellobonafide.com/products/serenol","sourceLabel":"Bonafide: product page"},"hiddenReason":"Not every fact is sourced yet: Supplement Facts amounts (chromium, pollen blend, royal jelly) not shown on page; No pregnancy, breastfeeding or medication warnings on page; Bonafide page heading reads ''180 tablets | 3-month supply'' while the single-box price sits beside it; tablet count per single box is not clearly stated; Amazon listing could not be read (amazon.com blocked fetch: robots_disallowed), so ASIN and match are unverified"}'::jsonb),
  ('p-bonafide-ristela', 'Bonafide Ristela', 'Bonafide', 'supplement', 'physical', 'Ristela is an oral tablet formulated to help improve blood flow to the vaginal area. It offers hormone-free support for orgasm and physical arousal for sexually active women.', '$58 single box (+$5 shipping); subscribe from $48/mo monthly, $129 per quarter, or $222 semiannually (brand page, Nov 2026)', 'http://hellobonafide.com/cdn/shop/files/Bonafide_RIS30DAYSTOCKB_Shopify_Cart_1.png?v=1756830036', 'https://hellobonafide.com/products/ristela', '["hormone-free","non-hormonal","supplement","herbal","menopause"]'::jsonb, '["sexual-health","supplement"]'::jsonb, '["Bonafide"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","allergens":"No allergen statement on page. Free-from claim: \"All of our products are free of hormones, parabens, soy, gluten, and GMOs.\"","sideEffects":"If you have specific concerns, we recommend that you speak with your doctor. These statements have not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure, or prevent any disease."}'::jsonb, null, null, null, 'brand', 'Product details are Bonafide''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Bonafide":"https://hellobonafide.com/products/ristela"},"warnings":["If you have specific concerns, we recommend that you speak with your doctor.","These statements have not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure, or prevent any disease."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://hellobonafide.com/products/ristela","what":"Product page: name, prices, Supplement Facts, other ingredients, directions, og:image"}],"ingredients":"Amount per two tablets: L-Arginine (as Arginine HCl) 800mg; L-Citrulline (as Citrulline HCl) 800mg; Rosvita® Rose Hips extract (Rosa rugosa Thunb.) (fruit) 200mg; Pycnogenol® French Maritime Pine Bark extract (Pinus pinaster) 80mg. Other ingredients: Microcrystalline cellulose, croscarmellose sodium, stearic acid, purified water, maltodextrin, hydroxypropyl methylcellulose, titanium dioxide, triacetin, polyethylene glycol, silica, sodium stearyl fumarate.","howToUse":{"intro":"Per Bonafide''s product page:","steps":["Take two tablets once per day, with or without food."],"sourceUrl":"https://hellobonafide.com/products/ristela","sourceLabel":"Bonafide: product page"}}'::jsonb),
  ('p-bonafide-noctera', 'Bonafide Noctera', 'Bonafide', 'sleep', 'physical', 'Noctera is a daily tablet designed to combat sleep disruptions caused by hormonal changes. It is intended for perimenopausal and menopausal women experiencing sleep challenges in the night. The page describes it as non-sedative and hormone-free.', '$39.99 single box (+$5 shipping); subscribe $33.99/mo monthly or $89.97 per quarter (brand page, Nov 2026)', 'http://hellobonafide.com/cdn/shop/files/Bonafide_NOC30DAYSTOCKB_Shopify_Cart_5c4b67a0-4746-4ae4-ab12-47916155ddac.png?v=1770760278', 'https://hellobonafide.com/products/noctera', '["sleep","menopause","perimenopause","hormone-free","non-hormonal","supplement"]'::jsonb, '["sleep","menopause","perimenopause"]'::jsonb, '["Bonafide"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","materials":"Key ingredients [amounts not shown on page]: Magnesium (as magnesium glycinate), GABA (gamma-aminobutyric acid), SAMe (S-adenosyl L-methionine disulfate p-toluenesulfonate), L-theanine, propyl gallate. Other ingredients: Microcrystalline cellulose, methacrylic acid copolymer, silicon dioxide, stearic acid, magnesium stearate, hydroxypropyl methylcellulose, sodium starch glycolate, color (calcium sulfate, magnesium carbonate), triethyl citrate, isomalt, glycerin, glycerol monostearate, polysorbate 80.","allergens":"No allergen statement on page. Page says: \"Noctera is hormone-free, non-GMO, and rigorously tested for quality, purity, and potency.\"","sideEffects":"Those taking medications should consult a healthcare provider before use. Every woman is different and if you have specific concerns, you should speak with your doctor or healthcare practitioner."}'::jsonb, null, null, null, 'brand', 'Product details are Bonafide''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Bonafid