  ('p-womaness-let-me-sleep', 'Womaness Let Me Sleep', 'Womaness', 'sleep', 'physical', 'Let Me Sleep is a drug-free, non-habit-forming capsule with melatonin, magnesium, GABA, chamomile and vitamin B6. Womaness pitches it for sleep and calm during menopause.', '$26.99 for 30 capsules (brand page, Nov 2026)', 'http://womaness.com/cdn/shop/files/Artboard-2_1024x1024.jpg?v=1774268784', 'https://womaness.com/collections/sleep/products/let-me-sleep', '["sleep","menopause","stress","drug-free","vegan","cruelty-free","hormone-free","supplement"]'::jsonb, '["sleep","menopause","mental-health"]'::jsonb, '["Womaness"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","materials":"[Amounts not shown on page] Vitamin B6 (as pyridoxal-5-phosphate), Magnesium (from Aquamin® Mg Seawater), GABA (gamma-aminobutyric acid), Chamomile (Matricaria chamomilla) (Flower Tops) Extract, Melatonin (as MicroActive®). Other: Hydroxypropyl Methylcellulose (Vegetable Capsule), Rice Flour, Sodium Alginate (from Marine brown algae), Microcrystalline Cellulose, Carnauba Wax.","allergens":"No allergen statement. Claims: Vegan, Gluten-Free, Cruelty-Free, No Estrogen or Added Hormones, Soy Free, Dermatologist & Allergy Tested.","sideEffects":"Not to be taken by pregnant or lactating women. If you are taking medications, have a medical condition, or have difficulty swallowing, consult your doctor before use. Do not drive or operate heavy machinery when using melatonin. Do not use in conjunction with alcoholic beverages. Do not use if clear neck seal is broken or missing. California Proposition 65 warning: can expose you to lead, known to cause cancer and birth defects or other reproductive harm."}'::jsonb, null, null, null, 'brand', 'Product details are Womaness''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Womaness":"https://womaness.com/collections/sleep/products/let-me-sleep"},"warnings":["Not to be taken by pregnant or lactating women.","If you are taking medications, have a medical condition, or have difficulty swallowing, consult your doctor before use.","Do not drive or operate heavy machinery when using melatonin.","Do not use in conjunction with alcoholic beverages.","Do not use if clear neck seal is broken or missing.","California Proposition 65 warning: can expose you to lead, known to cause cancer and birth defects or other reproductive harm."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://womaness.com/collections/sleep/products/let-me-sleep","what":"Product page: name, price, ingredients, claims, warnings incl. pregnancy/lactation and Prop 65, directions, og:image"}],"ingredients":"[Amounts not shown on page] Vitamin B6 (as pyridoxal-5-phosphate), Magnesium (from Aquamin® Mg Seawater), GABA (gamma-aminobutyric acid), Chamomile (Matricaria chamomilla) (Flower Tops) Extract, Melatonin (as MicroActive®). Other: Hydroxypropyl Methylcellulose (Vegetable Capsule), Rice Flour, Sodium Alginate (from Marine brown algae), Microcrystalline Cellulose, Carnauba Wax.","howToUse":{"intro":"Per Womaness''s product page:","steps":["Adults, take 1 capsule with water before bedtime as a dietary supplement or as directed by a doctor."],"sourceUrl":"https://womaness.com/collections/sleep/products/let-me-sleep","sourceLabel":"Womaness: product page"},"hiddenReason":"Not every fact is sourced yet: Supplement Facts amounts (melatonin dose etc.) not shown on page; Amazon listing could not be read (amazon.com blocked fetch: robots_disallowed), so ASIN and match are unverified"}'::jsonb),
  ('p-kindra-menorelief', 'Kindra MenoRelief', 'Kindra', 'menopause', 'physical', 'MenoRelief is an estrogen-free capsule with Pycnogenol and maca root. Kindra says it targets 11 symptoms of perimenopause and menopause, including hot flashes, night sweats, brain fog, memory and concentration.', '$39.00 for 30 capsules (sale price); 90-capsule option also listed, page shows ''Regular price $117.00'' without clearly tying it to a count (brand page, Nov 2026)', null, 'https://ourkindra.com/products/menorelief-supplement?variant=39776656293968', '["menopause","perimenopause","hormone-free","non-hormonal","vegan","supplement","herbal"]'::jsonb, '["menopause","perimenopause","supplement"]'::jsonb, '["Kindra"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","materials":"Pycnogenol®, Maca Root, Hydroxypropyl methylcellulose, rice hull extract, organic rice. Page FAQ: \"Each capsule contains 100mg of Pycnogenol®.\" Maca root amount not shown.","allergens":"No allergen statement. Claims: \"vegan, gluten-free, non-GMO, keto-friendly, and made without added sugar\"; \"free of hormones, gluten, and GMOs\"; Estrogen-Free.","sideEffects":"Consult your health provider prior to using if you are taking medications, whether prescription or over-the-counter. These statements have not been evaluated by the Food and Drug Administration."}'::jsonb, null, null, null, 'brand', 'Product details are Kindra''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Kindra":"https://ourkindra.com/products/menorelief-supplement?variant=39776656293968"},"warnings":["Consult your health provider prior to using if you are taking medications, whether prescription or over-the-counter.","These statements have not been evaluated by the Food and Drug Administration."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://ourkindra.com/products/menorelief-supplement?variant=39776656293968","what":"Product page: name, price, ingredients, Pycnogenol amount, claims, medication note, directions"},{"url":"https://ourkindra.com/collections/menopause","what":"Collection page linking the MenoRelief product URL"}],"ingredients":"Pycnogenol®, Maca Root, Hydroxypropyl methylcellulose, rice hull extract, organic rice. Page FAQ: \"Each capsule contains 100mg of Pycnogenol®.\" Maca root amount not shown.","howToUse":{"intro":"Per Kindra''s product page:","steps":["Take daily with water, preferably after a meal.","Page says take at least 100-200mg (1-2 capsules) of Pycnogenol per day for at least 90 days."],"sourceUrl":"https://ourkindra.com/products/menorelief-supplement?variant=39776656293968","sourceLabel":"Kindra: product page"},"optionsNote":"Options: 30 capsules, 90 capsules.","hiddenReason":"Not every fact is sourced yet: No Supplement Facts panel; maca root amount not shown; No pregnancy or breastfeeding info on page; Image: og:image URL was truncated in the fetch, so not reported; 90-capsule price unclear"}'::jsonb),
  ('p-stripes-the-inside-addition-menopause-probiotic', 'Stripes The Inside Addition Menopause Probiotic', 'Stripes', 'menopause', 'physical', 'The Inside Addition is a daily probiotic and vitamin capsule for people with perimenopause and menopause symptoms. The page says it supports bones and muscles and helps with stress, hot flashes and brain fog, and is hormone-free.', '$50.00 for 60 capsules; $42.50 with monthly Subscribe & Save (brand page, Nov 2026)', 'https://stripesbeauty.com/cdn/shop/files/hf_20260902_134815_15f0e2e4-53b4-429d-a36c-d9dc71c3e892_1.png?v=1789379512&width=2048', 'https://stripesbeauty.com/products/the-inside-addition', '["menopause","perimenopause","probiotic","hormone-free","vegan","cruelty-free","stress","supplement"]'::jsonb, '["menopause","perimenopause","bone-health"]'::jsonb, '["Stripes"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","materials":"[Amounts and CFU not shown on page] Vitamin D3, Vitamin E, Thiamin, Riboflavin, Niacin, Vitamin B3, Vitamin B6, Folate, Vitamin B12, Biotin, Pantothenic Acid, Ashwagandha extract, FFe6™ Enzyme Blend, Bacillus coagulans MTCC5856, Lactobacillus plantarum DR7, Rice concentrate, Hypromellose (veggie capsule), Spectra™ blend (green tea, broccoli sprout, onion, apple, quercetin, tomato, broccoli, camu camu, acerola, acai, turmeric, garlic, basil, oregano, cinnamon, carrot, elderberry, mangosteen, blackcurrant, blueberry, sweet cherry, raspberry, spinach, chokeberry, kale, blackberry, bilberry, Brussels sprout), Maltodextrin, Silicon Dioxide.","allergens":"No allergen statement. Claims: cruelty free, vegan, non-toxic, silicone free, sulfate free, paraben free, hormone free.","sideEffects":"This product is not intended to diagnose, treat, cure or prevent any disease."}'::jsonb, null, null, null, 'brand', 'Product details are Stripes''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"Stripes":"https://stripesbeauty.com/products/the-inside-addition"},"warnings":["This product is not intended to diagnose, treat, cure or prevent any disease."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://stripesbeauty.com/products/the-inside-addition","what":"Product page: name, price, ingredient list, strains, claims, directions, og:image"},{"url":"https://stripesbeauty.com/","what":"Homepage linking the product URL (iamstripes.com redirects here)"}],"ingredients":"[Amounts and CFU not shown on page] Vitamin D3, Vitamin E, Thiamin, Riboflavin, Niacin, Vitamin B3, Vitamin B6, Folate, Vitamin B12, Biotin, Pantothenic Acid, Ashwagandha extract, FFe6™ Enzyme Blend, Bacillus coagulans MTCC5856, Lactobacillus plantarum DR7, Rice concentrate, Hypromellose (veggie capsule), Spectra™ blend (green tea, broccoli sprout, onion, apple, quercetin, tomato, broccoli, camu camu, acerola, acai, turmeric, garlic, basil, oregano, cinnamon, carrot, elderberry, mangosteen, blackcurrant, blueberry, sweet cherry, raspberry, spinach, chokeberry, kale, blackberry, bilberry, Brussels sprout), Maltodextrin, Silicon Dioxide.","howToUse":{"intro":"Per Stripes''s product page:","steps":["Take 2 capsules daily with water."],"sourceUrl":"https://stripesbeauty.com/products/the-inside-addition","sourceLabel":"Stripes: product page"},"hiddenReason":"Not every fact is sourced yet: No Supplement Facts amounts, %DV or CFU counts on page; No allergen statement; No pregnancy, breastfeeding or medication warnings on page (contains ashwagandha and green tea); bone-health function is from page''s ''supports bones and muscles'' line"}'::jsonb),
  ('p-o-positiv-meno-menopause-capsules', 'O Positiv MENO Menopause Capsules', 'O Positiv', 'menopause', 'physical', 'MENO is a daily menopause supplement for multi-symptom relief. O Positiv recommends it for women with hot flashes, night sweats, occasional sleeplessness, occasional anxiousness and mood swings.', '$41.99 one-time for 1 bottle (30 servings, 2 capsules each, one-month supply); $34.99/bottle with monthly delivery (brand page, Nov 2026)', null, 'https://opositiv.com/products/meno-menopause-vitamin-capsule', '["menopause","hormone-free","non-hormonal","herbal","sleep","stress","supplement"]'::jsonb, '["menopause","sleep","mental-health"]'::jsonb, '["O Positiv"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","materials":"Per 2 capsules: Vitamin B6 2 mg; Vitamin D3 (cholecalciferol) 15 mcg; Chromium (as chromium picolinate) [amount not shown]; Ashwagandha KSM-66 root extract 300 mg; Chasteberry fruit extract 40 mg; Black Cohosh root extract 40 mg. Other ingredients: natural colors, rice flour, cellulose (vegetarian capsule), magnesium stearate.","allergens":"No allergen statement on page. Capsule is a vegetarian capsule; capsule option labeled ''Sugar-free''.","sideEffects":"Do not use MENO if you are pregnant or nursing. Consult your physician before taking if you have a medical condition, are taking any medications and/or any type of hormone therapy (including birth control pills). Do not use if cap seal is broken or missing. Keep out of reach of children."}'::jsonb, null, null, null, 'brand', 'Product details are O Positiv''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"O Positiv":"https://opositiv.com/products/meno-menopause-vitamin-capsule"},"warnings":["Do not use MENO if you are pregnant or nursing.","Consult your physician before taking if you have a medical condition, are