  ('p-o-positiv-flo-pms-capsules', 'O Positiv FLO PMS Capsules', 'O Positiv', 'supplement', 'physical', 'FLO is a sugar-free daily capsule for PMS with vitamin B6 and an herbal blend of chasteberry, lemon balm and dong quai. It is for people who get mood swings, period cramps or weight gain with their period.', '$31.99 one-time per bottle (30 capsules, monthly supply); $26.99/bottle with monthly delivery (brand page, Nov 2026)', null, 'https://opositiv.com/products/flo-pms-vitamin-capsule', '["pms","cramps","bloating","vegan","herbal","supplement","hormone-free"]'::jsonb, '["cramp-relief","mental-health","supplement"]'::jsonb, '["O Positiv"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","allergens":"No allergen statement on page. FAQ says FLO is vegan and non-GMO; capsule labeled sugar-free.","sideEffects":"These statements have not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure or prevent any disease."}'::jsonb, null, null, null, 'brand', 'Product details are O Positiv''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"O Positiv":"https://opositiv.com/products/flo-pms-vitamin-capsule"},"warnings":["These statements have not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure or prevent any disease."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://opositiv.com/products/flo-pms-vitamin-capsule","what":"FLO page: prices, capsule and gummy Supplement Facts, claims, directions"}],"ingredients":"Serving size 1 capsule, 30 servings per container: Vitamin B6 (as pyridoxine HCl) 20 mg (1176% DV); Proprietary Herbal Blend 86 mg: Chasteberry (Vitex agnus-castus) Fruit Extract, Lemon Balm (Melissa officinalis), Dong Quai (Angelica sinensis) Root. Other ingredients: Carnauba Wax, Cellulose (Vegetarian Capsule), Natural Colors, Titanium Dioxide.","howToUse":{"intro":"Per O Positiv''s product page:","steps":["Take 1 capsule a day.","Keep your bottle in a cool, dry place that you visit every day.","Take FLO for two menstrual cycles to feel full results."],"sourceUrl":"https://opositiv.com/products/flo-pms-vitamin-capsule","sourceLabel":"O Positiv: product page"},"hiddenReason":"Not every fact is sourced yet: no product photo yet (the brand page shows only a generic image); No pregnancy, breastfeeding or medication warnings on page (contains chasteberry and dong quai); Individual herb amounts in the 86 mg blend not disclosed; A FLO gummy (different formula: 111 mg blend, cane sugar) is sold on the same page; not in the sheet, could be a separate product"}'::jsonb),
  ('p-o-positiv-flo-ovarian-support-capsules-myo-d-chi', 'O Positiv FLO Ovarian Support Capsules (Myo + D-Chiro Inositol)', 'O Positiv', 'supplement', 'physical', 'Ovarian Support is a daily capsule with myo-inositol, D-chiro-inositol (40:1), DIM and folate to support healthy ovulation and hormone regulation. It is for people who want more consistent periods, are looking to balance testosterone levels, or have had unexpected weight gain. The page says it is for ages 18 and up.', '$41.99 one-time per bottle (30 servings, 3 capsules each), shown on sale at $29.99; $29.99/bottle with monthly delivery (brand page, Nov 2026)', null, 'https://opositiv.com/products/flo-ovarian-support-vitamin-capsules', '["pcos","irregular","hormone-support","fertility","supplement","acne"]'::jsonb, '["fertility","supplement"]'::jsonb, '["O Positiv"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","sideEffects":"Consult your physician before taking if you have a medical condition, or are taking any medications. If you are using medication for diabetes or low blood sugar, consult your health care professional. Do not use if the cap seal is broken or missing. Keep out of reach of children."}'::jsonb, null, null, null, 'brand', 'Product details are O Positiv''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, false, '{"whereToBuyLinks":{"O Positiv":"https://opositiv.com/products/flo-ovarian-support-vitamin-capsules"},"warnings":["Consult your physician before taking if you have a medical condition, or are taking any medications.","If you are using medication for diabetes or low blood sugar, consult your health care professional.","Do not use if the cap seal is broken or missing.","Keep out of reach of children."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://opositiv.com/products/flo-ovarian-support-vitamin-capsules","what":"Ovarian Support page: prices, Supplement Facts, warnings, directions"}],"ingredients":"Serving size 3 capsules, 30 servings per container: Folate (as folic acid) 680 mcg DFE (170% DV); Myo-Inositol 2,000 mg; Diindolylmethane (DIM) 100 mg; D-Chiro-Inositol (from carob pods extract) 50 mg. Other ingredients: Cellulose (vegetarian capsule), magnesium stearate, natural colors.","howToUse":{"intro":"Per O Positiv''s product page:","steps":["Take 3 FLO Ovarian Support capsules once a day, with water.","Keep your bottle in a cool, dry place that you visit every day."],"sourceUrl":"https://opositiv.com/products/flo-ovarian-support-vitamin-capsules","sourceLabel":"O Positiv: product page"},"hiddenReason":"Not every fact is sourced yet: no product photo yet (the brand page shows only a generic image); No allergen statement; No pregnancy or breastfeeding info on page (relevant: marketed for ovulation/fertility); ''acne'' tag not stated on page; page mentions unwanted facial hair from testosterone. Review"}'::jsonb),
  ('p-o-positiv-uro-urinary-tract-health-capsules', 'O Positiv URO Urinary Tract Health Capsules', 'O Positiv', 'supplement', 'physical', 'URO Urinary Tract Health is a daily, antibiotic-free capsule with Pacran cranberry, D-mannose and vitamin C. It is for women prone to urinary tract irritation or who want to protect urinary tract health, including sexually active women.', '$31.99 one-time per bottle (30 servings, 2 capsules each); $26.99/bottle with monthly delivery (brand page, Nov 2026)', 'https://cdn.shopify.com/s/files/1/0588/9340/2261/files/URO-UT-Cap-PDP-Shadow-optimized.webp?v=1762840007', 'https://opositiv.com/products/uro-urinary-health-capsules', '["uti","drug-free","supplement"]'::jsonb, '["uti-prevention","supplement"]'::jsonb, '["O Positiv"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not FDA-approved (FDA does not approve supplements)","allergens":"No allergen statement on page. Capsule labeled sugar-free.","sideEffects":"If pregnant or nursing, ask your healthcare professional before use. Consult your physician before taking if you have a medical condition, or are taking any medications. Do not use if cap seal is broken or missing. Keep out of reach of children."}'::jsonb, null, null, null, 'brand', 'Product details are O Positiv''s own, from its product page (read Nov 2026). Regulatory status checked in openFDA where it applies.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"O Positiv":"https://opositiv.com/products/uro-urinary-health-capsules"},"warnings":["If pregnant or nursing, ask your healthcare professional before use.","Consult your physician before taking if you have a medical condition, or are taking any medications.","Do not use if cap seal is broken or missing. Keep out of reach of children."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"addedFrom":"founder sheet, Nov 2 2026 (Ameera)","researchSources":[{"url":"https://opositiv.c